def build_dynamic_country_viral_feeds(hist_obj, count_countries=8, sub_pillar="GEOPOLITICS"):
    """
    V48 ALL-46-COUNTRY + GOOGLE TRENDS VIRAL TOPIC HARVESTER:
    1. Rotates across all 46+ countries in `GLOBAL_ALL_COUNTRIES_ROTATION`, skipping recently used countries.
    2. Queries Google Trends Real-Time Viral RSS (`https://trends.google.com/trending/rss?geo={iso2}`)
       so we capture 100K-1M+ search surges in USA, UK, Indonesia, Brazil, Germany, Japan, South Korea,
       Philippines, Malaysia, Turkey, Saudi Arabia, South Africa, Nigeria, Australia, Canada, France, etc.!
    3. Queries clean category-matched Google News RSS for each rotating country using valid `OR` syntax!
    """
    last_c = set(hist_obj.get("last_countries", [])[-10:])
    c_idx = int(hist_obj.get("country_rot_idx", 0))
    chosen_tuples = []
    for step in range(len(GLOBAL_ALL_COUNTRIES_ROTATION)):
        cand_t = GLOBAL_ALL_COUNTRIES_ROTATION[(c_idx + step) % len(GLOBAL_ALL_COUNTRIES_ROTATION)]
        if cand_t[0] not in last_c and (cand_t[0] != "INDIA" or sub_pillar == "INDIA_TRENDING"):
            chosen_tuples.append(cand_t)
            if len(chosen_tuples) >= count_countries:
                break
    if not chosen_tuples:
        chosen_tuples = GLOBAL_ALL_COUNTRIES_ROTATION[:count_countries]
    hist_obj["country_rot_idx"] = (c_idx + count_countries) % len(GLOBAL_ALL_COUNTRIES_ROTATION)

    cat_or_clause = {
        "STOCK_MARKETS": "(economy OR market OR trade OR billion OR bank OR tariff OR oil OR currency)",
        "BUSINESS": "(economy OR market OR trade OR billion OR bank OR tariff OR oil OR investment)",
        "AI_ROBOTICS": "(AI OR semiconductor OR robotics OR chip OR technology OR cyber OR startup)",
        "TECHNOLOGY": "(technology OR AI OR semiconductor OR cyber OR innovation OR telecom OR digital)",
        "SCIENCE": "(space OR satellite OR rocket OR science OR discovery OR energy OR nuclear OR climate)",
        "MIND_BLOWING_FACTS": "(discovery OR mystery OR ancient OR archaeological OR engineering OR record OR scientists)",
        "HEALTH": "(health OR medical OR biotech OR hospital OR vaccine OR clinical OR breakthrough)",
        "VIRAL_UNDERDOG_SPORTS": "(prodigy OR athlete OR rider OR championship OR record OR upset OR medal OR tournament)",
        "SPORTS": "(championship OR athlete OR tournament OR record OR olympic OR racing OR trophy)",
        "ENTERTAINMENT": "(cinema OR film OR box office OR streaming OR gaming OR media OR festival)"
    }.get(sub_pillar, "(geopolitics OR military OR defense OR government OR sanctions OR summit OR crisis OR treaty)")

    dynamic_feeds = []
    for c_name, iso2, _ in chosen_tuples:
        # 1. Google Trends Real-Time Viral Feed for this country (100K+ search spikes!)
        if sub_pillar in ("GEOPOLITICS", "GLOBAL_POWERS", "VIRAL_UNDERDOG_SPORTS", "UNDERRATED_GEOPOLITICS"):
            dynamic_feeds.append((
                f"Google Trends Viral [{c_name}]",
                f"https://trends.google.com/trending/rss?geo={iso2}"
            ))
        # 2. Country Category-Specific Breaking Wire (Valid OR syntax!)
        q_doc = urllib.parse.quote(f'"{c_name}" {cat_or_clause} when:2d -site:aljazeera.com')
        dynamic_feeds.append((
            f"Global Country Wire [{c_name} • {sub_pillar}]",
            f"https://news.google.com/rss/search?q={q_doc}&hl=en-US&gl=US&ceid=US:en"
        ))
    return dynamic_feeds

