def ensure_cached_playlist_map(yt, hist_obj):
    _ = sync_all_8_playlists_and_organize_channel(yt)
    """
    V52 COMPLETE 8-PLAYLIST MAPPER (Guarantees `SPORTS` & `VIRAL_UNDERDOG_SPORTS` are ALWAYS mapped!):
    Refreshes if `VIRAL_UNDERDOG_SPORTS` or `SPORTS` or `ENTERTAINMENT` is missing from an older cached dict!
    """
    if hist_obj is not None and isinstance(hist_obj.get("cached_playlist_map"), dict):
        cmap = hist_obj["cached_playlist_map"]
        if cmap.get("SPORTS") and not cmap.get("VIRAL_UNDERDOG_SPORTS"):
            cmap["VIRAL_UNDERDOG_SPORTS"] = cmap["SPORTS"]
        if len(cmap) >= 8 and cmap.get("SPORTS") and cmap.get("VIRAL_UNDERDOG_SPORTS"):
            return cmap
    pl_map = {}
    try:
        resp = yt.playlists().list(part="snippet", mine=True, maxResults=50).execute()
        for item in resp.get("items", []):
            pid = item.get("id")
            ptitle = str((item.get("snippet") or {}).get("title", "")).lower()
            if not pid or not ptitle:
                continue
            for p_key, kw_list in PLAYLIST_KEYWORD_MATCHERS.items():
                if any(kw in ptitle for kw in kw_list):
                    pl_map[p_key] = pid
        if pl_map and hist_obj is not None:
            hist_obj["cached_playlist_map"] = pl_map
            save_published_history(hist_obj)
            print(f"📂 [Cached {len(pl_map)} Channel Category Playlists] Ready for automatic playlist assignment!", flush=True)
    except Exception as e:
        print("⚠️ Playlist cache lookup note:", str(e)[:90], flush=True)
    return pl_map

def add_video_to_category_playlist_and_comment(yt, video_id, pillar, summary_takeaway, playlist_map, linked_long_url=None, is_short=False):
    """
    V48 AUTOMATIC 8-PLAYLIST ASSIGNER + LINKED SHORT COMMENT:
    1. Adds every Long Documentary (and Short) into its exact matching Category Playlist on `@WorldTalkBrief`
       (`Global Geopolitics`, `AI & Robotics`, `Mind-Blowing Facts`, `Space & NASA`, `Business & Markets`,
       `Health & Biotech`, `Global Sports Arena`, `Cinema & Pop Culture`).
    2. On Shorts, also posts the linked full-documentary comment!
    """
    if not video_id:
        return
    try:
        hist_obj = load_published_history()
        active_pl_map = playlist_map if (playlist_map and len(playlist_map) >= 4) else ensure_cached_playlist_map(yt, hist_obj)
        core_hub = PILLAR_TO_CORE_HUB.get(pillar, pillar)
        amap = active_pl_map or {}
        target_pid = (
            amap.get(pillar)
            or amap.get(core_hub)
            or (amap.get("SPORTS") if "SPORT" in str(pillar).upper() else None)
            or (amap.get("BUSINESS") if "MARKET" in str(pillar).upper() or "BIZ" in str(pillar).upper() else None)
            or (amap.get("TECHNOLOGY") if "AI" in str(pillar).upper() or "TECH" in str(pillar).upper() else None)
            or amap.get("WORLD")
        )
        if target_pid:
            yt.playlistItems().insert(
                part="snippet",
                body={
                    "snippet": {
                        "playlistId": target_pid,
                        "position": 0,
                        "resourceId": {
                            "kind": "youtube#video",
                            "videoId": video_id
                        }
                    }
                }
            ).execute()
            print(f"📂 [Added to Top (Position #0) of Channel Playlist '{pillar}'] Video {video_id} -> Playlist {target_pid}", flush=True)
    except Exception as pe:
        print("⚠️ Playlist insert note:", str(pe)[:90], flush=True)

    if not linked_long_url:
        return
    try:
        comment_txt = (
            f"🔴 WATCH THE FULL DOCUMENTARY VIDEO HERE: {linked_long_url}\n\n"
            f"📌 KEY TAKEAWAY: {summary_takeaway}\n"
            f"What is your perspective on this? Share your thoughts in the comments! 👇"
        )
        yt.commentThreads().insert(
            part="snippet",
            body={
                "snippet": {
                    "videoId": video_id,
                    "topLevelComment": {
                        "snippet": {
                            "textOriginal": comment_txt
                        }
                    }
                }
            }
        ).execute()
        print(f"💬 [YouTube Linked Documentary Comment Posted] on Short {video_id} -> {linked_long_url}", flush=True)
    except Exception:
        pass

