def extract_primary_topic_anchor(dossier):
    """
    V55 HEADLINE-LOCKED PROPER-ENTITY & ACRONYM TOPIC ANCHOR EXTRACTOR:
    1. Always prioritizes 2-to-4 letter uppercase brands/acronyms in the headline (`BMW`, `BYD`, `TSMC`, `IDF`,
       `NATO`, `BRICS`, `OPEC`, `ISRO`, `NASA`, `UEFA`, `FIFA`) and named entities in `raw_t` FIRST so polluted
       secondary claims (like `MTG Q3`) can NEVER hijack the topic anchor!
    """
    raw_t = str(dossier.get("original_rss_headline") or dossier.get("title", ""))
    facts_head = " ".join(str(x) for x in (dossier.get("raw_facts") or [])[:1])
    comb_text = f"{raw_t}. {facts_head}"
    low = raw_t.lower()
    acronyms_in_title = [
        m.group(1) for m in re.finditer(r"\b([A-Z]{2,5})\b", raw_t)
        if m.group(1) not in {"WHY", "HOW", "THE", "AND", "FOR", "NEW", "TOP", "BIG", "WAR", "NOW", "OUT", "OFF", "Q1", "Q2", "Q3", "Q4", "CEO", "CFO", "USD", "EUR", "GBP", "INR"}
    ]
    if acronyms_in_title:
        lead_acr = acronyms_in_title[0]
        # Pair the acronym with the main capitalized subject noun in the title if present
        cap_nouns = [
            w for w in re.findall(r"\b[A-Z][a-zA-Z0-9\-]{2,}\b", raw_t)
            if w.upper() != lead_acr and w.lower() not in HEADLINE_STOP_VERBS_ADJS and w.upper() not in {"Q1", "Q2", "Q3", "Q4", "WHY", "HOW", "THE"}
        ]
        if cap_nouns:
            return f"{lead_acr} {cap_nouns[0]}"
        return lead_acr

    for p_key, (wiki_page, _, _) in PERSON_WIKI_MAP.items():
        if re.search(rf"\b{re.escape(p_key)}\b", low):
            return wiki_page

    for word_key, (_, wiki_exact, _) in CONCRETE_WIKI_PROPS.items():
        if re.search(rf"\b{re.escape(word_key)}\b", low):
            return wiki_exact

    clickbait_hook_stops = {
        "the", "this", "that", "why", "how", "what", "when", "where", "who", "inside", "behind",
        "donation", "empire", "collapse", "teen", "teenager", "prodigy", "bold", "youth", "gamble",
        "massive", "shocking", "historic", "signs", "signed", "deal", "year", "years", "old",
        "sudden", "secret", "truth", "breaking", "world", "talk", "brief", "million", "billion",
        "thousand", "hundred", "october", "november", "december", "january", "february", "march",
        "april", "may", "june", "july", "august", "september", "monday", "tuesday", "wednesday",
        "thursday", "friday", "saturday", "sunday", "week", "today", "yesterday"
    }

    # 1. Look for Multi-Word Capitalized Proper Noun Phrases in `comb_text` (e.g. 'Matthew Wright', 'Ellen DeGeneres', 'Angel City FC', 'Maddy DiMaria')
    proper_phrases = []
    for m_pr in re.finditer(r"\b([A-Z][a-zA-Z0-9\-]+(?:\s+[A-Z][a-zA-Z0-9\-]+){1,3})\b", comb_text):
        cand_p = m_pr.group(1).strip()
        p_toks = [w for w in cand_p.split() if w.lower() not in clickbait_hook_stops and w.lower() not in HEADLINE_STOP_VERBS_ADJS]
        if len(p_toks) >= 2:
            clean_p = " ".join(p_toks[:3])
            cl_low = clean_p.lower()
            replaced = False
            for idx_p, ex_p in enumerate(proper_phrases):
                if ex_p.lower() in cl_low:
                    proper_phrases[idx_p] = clean_p
                    replaced = True
                    break
                if cl_low in ex_p.lower():
                    replaced = True
                    break
            if not replaced:
                proper_phrases.append(clean_p)
    if proper_phrases:
        return fit_whole_words_limit(" ".join(proper_phrases[:2]), 38)

    # 2. Fallback to meaningful non-clickbait nouns from title + first fact
    content_nouns = [
        w for w in re.findall(r"[A-Za-z]{4,}", comb_text)
        if w.lower() not in HEADLINE_STOP_VERBS_ADJS and w.lower() not in clickbait_hook_stops
    ]
    seen_cn = []
    for cn in content_nouns:
        if cn.lower() not in [x.lower() for x in seen_cn]:
            seen_cn.append(cn)
        if len(seen_cn) >= 3:
            break
    return " ".join(seen_cn).title() if seen_cn else "Global Case Study"

def build_100_percent_original_youtube_title(raw_title, pillar, c_prof, topic_anchor, is_update=False):
    """
    V55 HIGH-CTR THINK SCHOOL / NITISH RAJPUT VIRAL DOCUMENTARY TITLE ENGINE:
    - Converts flat lowercase RSS headlines (like 'BMW reports lower Q3 earnings') into high-intrigue,
      Title-Cased documentary hooks with real stakes!
    """
    clean_t = re.sub(r"\s*\|\s*[A-Za-z0-9_\s]+Explained$", "", str(raw_title or "").strip(), flags=re.I).strip()
    clean_t = re.sub(r"\s+[-–—]\s+(?:BBC|Reuters|AP|The Guardian|CNN|DW|France 24|ESPN).*$", "", clean_t, flags=re.I).strip()
    small_words = {"a", "an", "the", "in", "on", "at", "to", "for", "of", "and", "or", "vs", "by", "with", "from", "into"}
    tc_words = []
    for idx_w, w in enumerate(clean_t.split()):
        if w.isupper() and len(w) >= 2:
            tc_words.append(w)
        elif idx_w > 0 and w.lower() in small_words:
            tc_words.append(w.lower())
        else:
            tc_words.append(w[0].upper() + w[1:] if len(w) > 1 else w.upper())
    clean_t = " ".join(tc_words)
    prefix = "BREAKING: " if is_update and not clean_t.lower().startswith(("why ", "how ", "breaking")) else ""
    base_t = f"{prefix}{clean_t}".strip()
    if not base_t.lower().startswith(("why ", "how ", "inside ", "the ", "breaking")) and "?" not in base_t and ":" not in base_t and len(base_t) <= 58:
        base_t = f"How {base_t}: The Real Story"
    elif not base_t.lower().startswith(("why ", "how ", "inside ", "the ", "breaking")) and "?" not in base_t and len(base_t) <= 68:
        base_t = f"Why {base_t}"
    if len(base_t) <= 88:
        return base_t
    words = base_t.split()
    out = []
    for w in words:
        if len(" ".join(out + [w])) <= 86:
            out.append(w)
        else:
            break
    return " ".join(out)

PUBLISHER_NAMES_STRIP_REGEX = (
    r"\b(?:Al\s*Jazeera(?:\s+English)?|BBC(?:\s+News|\s+World)?|CNN(?:\s+International)?|"
    r"The\s+Guardian(?:\s+World)?|Reuters|Associated\s+Press|AP\s+News|DW(?:\s+News)?|"
    r"France\s*24|NDTV|The\s+Hindu|Indian\s+Express|Times\s+of\s+India|New\s+York\s+Times|"
    r"Washington\s+Post|Bloomberg|CNBC|TechCrunch|The\s+Verge|Ars\s+Technica|SciTechDaily|"
    r"Phys\.org|MedicalXpress|Space\.com|Hollywood\s+Reporter|Google\s+News)\b"
)

def strip_news_publisher_mentions(text_str):
    """
    100% ZERO EXTERNAL NEWS CHANNEL/ARTICLE ATTRIBUTION GUARD:
    Ensures we NEVER mention 'Al Jazeera', 'BBC', 'CNN', 'The Guardian', 'Reuters', etc.
    in our spoken script, HUD overlays, or video descriptions!
    """
    if not text_str:
        return ""
    s = str(text_str)
    s = re.sub(r"\b(?:according to|reported by|as reported by|verified data from|reports from|speaking to|told|tells)\s+" + PUBLISHER_NAMES_STRIP_REGEX + r"\s*,?\s*", "", s, flags=re.I)
    s = re.sub(PUBLISHER_NAMES_STRIP_REGEX + r"\s+(?:reported|reports|revealed|stated|said|warned|confirmed|noted|said)\s*,?\s*(?:that\s+)?", "", s, flags=re.I)
    s = re.sub(r",?\s*(?:according to\s+)?" + PUBLISHER_NAMES_STRIP_REGEX + r"(?:\s+said|\s+reported|\s+added)?\.?", ".", s, flags=re.I)
    s = re.sub(PUBLISHER_NAMES_STRIP_REGEX, "international analysts", s, flags=re.I)
    s = re.sub(r"\s+", " ", s).strip()
    if s and s[0].islower():
        s = s[0].upper() + s[1:]
    return s

def paraphrase_into_original_creator_voice(raw_fact, beat_idx=0, dossier=None):
    s = strip_news_publisher_mentions(str(raw_fact or "").strip().rstrip("."))
    # Fix awkward 'Verified data from X, Y' or trailing ', X added' news wire fragments so the public understands every sentence!
    s = re.sub(r"(?i)^verified data from\s+([^,]+),\s*", r"Internal records from \1 show that ", s)
    # If a trailing ', [Surname] added/said' appears, clarify their role if known from dossier person_role_directory!
    if dossier and isinstance(dossier.get("person_role_directory"), dict):
        p_dir = dossier["person_role_directory"]
        for key_low, (w_n, d_n, r_lbl) in p_dir.items():
            if len(key_low) >= 4:
                s = re.sub(
                    rf",\s*{re.escape(d_n.split()[-1])}\s+(?:added|said|noted|stated|warned)\.?$",
                    f", according to {r_lbl.lower()} {d_n}",
                    s, flags=re.I
                )
    s = re.sub(r",\s*([A-Z][a-z]{3,16})\s+added\.?$", r", defense counsel  confirmed", s)
    s = re.sub(r",\s*the\s+([a-z]+(?:\s+[a-z]+)?'s?\s+association)\s+said\.?$", r", according to the ", s, flags=re.I)

    rewrites = [
        (r"(?i)^in a study of\b", "When researchers analyzed"),
        (r"(?i)\bmounted a stunning comeback\b", "pulled off a historic turnaround"),
        (r"(?i)\bholds off far right\b", "secured a decisive victory"),
        (r"(?i)\bin effect,\s*ambushed\b", "unexpectedly ambushed"),
        (r"(?i)\bmore than (\d+)", r"over \1"),
        (r"(?i)\bapproximately (\d+)", r"nearly \1"),
        (r"(?i)\bit is\b", "it's"),
        (r"(?i)\bthat is\b", "that's"),
        (r"(?i)\bthere is\b", "there's"),
        (r"(?i)\bdo not\b", "don't"),
        (r"(?i)\bdoes not\b", "doesn't"),
        (r"(?i)\bdid not\b", "didn't"),
        (r"(?i)\bcannot\b", "can't"),
        (r"(?i)\bhas not\b", "hasn't"),
        (r"(?i)\bhave not\b", "haven't")
    ]
    for pat, rep in rewrites:
        s = re.sub(pat, rep, s)

    s = re.sub(r"\s+", " ", s).strip().rstrip(",;:")
    if not s:
        return ""
    s = s[0].upper() + s[1:]
    return f"{s}."

def extract_story_entities(dossier):
    if dossier.get("visual_anchors"):
        return dossier["visual_anchors"]

    text = f"{dossier['title']} {' '.join(dossier.get('raw_facts', [])[:3])}"
    c_prof = dossier["country_profile"]
    pillar = dossier.get("pillar", "WORLD")
    ents = []
    if dossier.get("wiki_hook_entity"):
        ents.append(dossier["wiki_hook_entity"])

    low = text.lower()
    for word_key, (_, wiki_exact, _) in CONCRETE_WIKI_PROPS.items():
        if re.search(rf"\b{re.escape(word_key)}\b", low) and wiki_exact not in ents:
            ents.append(wiki_exact)

    for k, (wiki_name, _, _) in PERSON_WIKI_MAP.items():
        if re.search(rf"\b{re.escape(k)}\b", low):
            if wiki_name not in ents:
                ents.append(wiki_name)

    anchor = extract_primary_topic_anchor(dossier)
    if anchor and anchor not in ents:
        ents.append(anchor)

    if pillar == "WORLD" and not c_prof.get("is_global_topic"):
        for fb in [c_prof["capital"], c_prof["name"].title()]:
            if fb not in ents:
                ents.append(fb)
    return ents[:8] if ents else ["Global Case Study"]

def resolve_country_or_domain_profile(title, raw_facts_list, pillar_name="WORLD"):
    headline_low = title.lower()
    body_low = " ".join(raw_facts_list[:3]).lower()
    comb_us_check = f"{headline_low} {body_low}"
    # CRITICAL V61 FIX 1: Disambiguate U.S. State of Georgia & U.S. Sports Leagues (NFL, NBA, MLB, NHL, NCAA, Super Bowl)
    # so "Jaguars' Blockbuster Trade: Jordan Davis, Super Bowl Gamble" maps to UNITED STATES (NEVER Jordan/Amman!)
    if "georgia" in comb_us_check and any(us_k in comb_us_check for us_k in ["senate", "gop", "republican", "democrat", "democratic", "atlanta", "ossoff", "warnock", "kemp", "collins", "trump", "biden", "congress", "midterm", "governor", "bulldogs", "sec "]):
        return build_country_dict_from_db("united states", is_global_topic=False)

    if any(us_sp in comb_us_check for us_sp in [
        "indian wells", "indiana", "indianapolis", "coco gauff", "jessica pegula", "jessia pegula",
        "celtics", "boston celtics", "jason tatum", "jayson tatum", "milwaukee bucks", "new york knicks",
        "nfl", "super bowl", "jacksonville jaguars", "philadelphia eagles", "kansas city chiefs", "dallas cowboys",
        "san francisco 49ers", "baltimore ravens", "buffalo bills", "green bay packers", "detroit lions", "new york jets",
        "new york giants", "chicago bears", "pittsburgh steelers", "new england patriots", "miami dolphins", "houston texans",
        "nba", "los angeles lakers", "golden state warriors", "mlb", "new york yankees", "los angeles dodgers",
        "nhl", "ncaa", "wall street", "federal reserve", "pentagon", "white house", "capitol hill", "silicon valley"
    ]):
        return build_country_dict_from_db("united states", is_global_topic=False)

    # CRITICAL V61 FIX 2: Guard ambiguous country names that are common first/last names ('Jordan Davis', 'Michael Jordan', 'Jordan Love', 'Chad Gable')
    jordan_is_country = any(jk in comb_us_check for jk in ["amman", "king abdullah", "hashemite", "aqaba", "jordanian", "middle east", "west bank", "israel", "syria", "iraq"])

    best_match = None
    best_pos = 9999
    for dem, c_mapped in DEMONYM_TO_COUNTRY.items():
        if c_mapped == "JORDAN" and not jordan_is_country:
            continue
        pos = headline_low.find(dem)
        if pos != -1 and pos < best_pos:
            best_pos = pos
            best_match = c_mapped
    for c_name in COUNTRY_GEO_DB.keys():
        if c_name == "JORDAN" and not jordan_is_country:
            continue
        m = re.search(rf"\b{re.escape(c_name.lower())}\b", headline_low)
        if m and m.start() < best_pos:
            best_pos = m.start()
            best_match = c_name

    if best_match:
        return build_country_dict_from_db(best_match, is_global_topic=False)

    # CRITICAL V47 ANTI-INDIA-POLLUTION GUARD:
    # If the headline (`headline_low`) did NOT mention India/Indian/Delhi/Mumbai/Modi/ISRO,
    # NEVER allow a secondary mention of India in `body_low` to tag an international story as `INDIA` (`🇮🇳`)!
    clean_hl_no_us_indian = re.sub(r"\b(indian wells|indiana|indianapolis|west indies|american indian)\b", "", headline_low)
    india_in_headline = any(ik in clean_hl_no_us_indian for ik in ["india", "indian", "new delhi", "delhi", "mumbai", "bengaluru", "modi", "isro", "rbi", "bcci", "sensex", "nifty", "rupee"])

    for dem, c_mapped in DEMONYM_TO_COUNTRY.items():
        if c_mapped == "INDIA" and not india_in_headline:
            continue
        if re.search(rf"\b{re.escape(dem.strip())}\b", body_low):
            return build_country_dict_from_db(c_mapped, is_global_topic=False)
    for c_name in COUNTRY_GEO_DB.keys():
        if c_name == "INDIA" and not india_in_headline:
            continue
        if c_name == "JORDAN" and not jordan_is_country:
            continue
        if re.search(rf"\b{re.escape(c_name.lower())}\b", body_low):
            return build_country_dict_from_db(c_name, is_global_topic=False)

    hub_names = {
        "MIND_BLOWING_FACTS": ("MIND-BLOWING FACT", "Global Discovery", "World Wonders"),
        "TECHNOLOGY": ("GLOBAL TECH & AI", "Silicon Valley", "Global Tech Sector"),
        "SCIENCE": ("SPACE & SCIENCE", "Global Research", "Scientific Community"),
        "HEALTH": ("MEDICAL SCIENCE", "Global Health", "Biotech & Medicine"),
        "BUSINESS": ("GLOBAL MARKETS", "Wall Street", "Global Economy"),
        "SPORTS": ("SPORTS ARENA", "International Arena", "Global Sports"),
        "ENTERTAINMENT": ("GLOBAL CINEMA", "Hollywood", "Entertainment Industry"),
        "WORLD": ("INTERNATIONAL", "United Nations", "Global Affairs")
    }
    h_name, h_cap, h_reg = hub_names.get(pillar_name, ("GLOBAL BRIEFING", "International Hub", "Global"))
    return {
        "name": h_name,
        "iso2": "UN",
        "iso3": "USA",
        "capital": h_cap,
        "population": "8 billion",
        "region": h_reg,
        "lat": 37.386,
        "lon": -122.083,
        "flag_img": None,
        "is_global_topic": True
    }

def build_country_dict_from_db(c_name, is_global_topic=False):
    c_name = str(c_name).upper().strip()
    iso2, iso3, cap, pop, reg, lat, lon = COUNTRY_GEO_DB.get(c_name, COUNTRY_GEO_DB["UNITED STATES"])
    c_prof = {
        "name": c_name, "iso2": iso2, "iso3": iso3, "capital": cap,
        "population": pop, "region": reg, "lat": lat, "lon": lon,
        "flag_img": None, "is_global_topic": is_global_topic
    }
    try:
        fr = requests.get(f"https://flagcdn.com/w160/{iso2.lower()}.png", headers=HEADERS_WEB, timeout=5)
        if fr.status_code == 200 and len(fr.content) > 500:
            fp = f"temp/flag_{iso2}.png"
            with open(fp, "wb") as f:
                f.write(fr.content)
            c_prof["flag_img"] = Image.open(fp).convert("RGBA")
    except Exception:
        pass
    return c_prof

def normalize_pub_date(raw_date):
    if not raw_date:
        return datetime.utcnow().strftime("%Y-%m-%d")
    cleaned = re.sub(r"\s+", " ", str(raw_date)).strip()
    return cleaned[:25]

def classify_story_mood_and_category(title, claims_text, pillar_name="WORLD"):
    comb = f"{title} {claims_text}".lower()
    if any(k in comb for k in ["alexander", "ancient", "empire", "pharaoh", "roman", "dynasty", "archaeolog", "century bc", "tomb", "king ", "emperor", "warrior", "civilization", "persia", "babylon"]):
        return "ancient_history_epic"
    if any(k in comb for k in ["investigation", "scandal", "secret", "classified", "leaked", "intelligence", "cia", "fbi", "pentagon", "sanctions", "espionage", "dossier", "corruption"]):
        return "investigative_thriller"
    if any(k in comb for k in ["paradox", "quantum", "black hole", "dimension", "time travel", "consciousness", "universe", "unbelievable", "mystery", "impossible", "gravity"]):
        return "mind_bending_wonder"
    if any(k in comb for k in ["patient", "hospital", "children", "family", "survival", "rescued", "heart", "longevity", "life-saving", "cure", "humanity"]):
        return "emotional_human_story"
    p_cfg = CATEGORY_FEEDS.get(pillar_name, CATEGORY_FEEDS["WORLD"])
    return p_cfg.get("bgm_mood", "dark_geopolitics")


def resolve_google_or_bing_redirect_url(raw_link, headline_title=""):
    """
    V58 REAL PUBLISHER ARTICLE URL DECODER (`googlenewsdecoder` + Bing `apiclick` URL unwrapper):
    Unwraps `news.google.com/rss/articles/...` and `bing.com/news/apiclick.aspx?...&url=...`
    to the true original publisher URL (Reuters, BBC, AP, Bloomberg, CNBC, ESPN, The Verge, etc.)
    so our scraper can harvest the authentic 1080p `og:image`, `<figure>` press photos, and `<video>`!
    """
    link_s = str(raw_link or "").strip()
    if not link_s:
        return ""
    if "bing.com/news/apiclick" in link_s or "url=http" in link_s:
        try:
            qs = urllib.parse.parse_qs(urllib.parse.urlparse(link_s).query)
            if qs.get("url"):
                return str(qs["url"][0]).strip()
        except Exception:
            pass
    if "news.google.com" in link_s:
        try:
            from googlenewsdecoder import new_decoderv1
            dec = new_decoderv1(link_s, interval=0.5)
            if isinstance(dec, dict) and dec.get("status") and dec.get("decoded_url"):
                return str(dec["decoded_url"]).strip()
        except Exception:
            pass
        # Fallback: resolve headline via Bing News RSS `url=` parameter in <1.5s!
        if headline_title and len(headline_title) >= 12:
            try:
                q_clean = " ".join(re.findall(r"[A-Za-z0-9\-]+", headline_title)[:7])
                b_rss = f"https://www.bing.com/news/search?q={urllib.parse.quote(q_clean)}&format=rss"
                br = requests.get(b_rss, headers=HEADERS_WEB, timeout=3.5)
                for m_u in re.findall(r'url=(https?%3a%2f%2f[^&"<>\s]+)', br.text, flags=re.I)[:4]:
                    cand_dec = urllib.parse.unquote(m_u)
                    if not any(b in cand_dec.lower() for b in ["aljazeera", "msn.com", "yahoo.com"]):
                        return cand_dec
            except Exception:
                pass
    return link_s


def auto_detect_true_sub_pillar_and_hub_v64(title, summary, requested_sub_pillar):
    """
    V64 TRUE DOMAIN & PILLAR LOCK:
    When a breaking viral story is harvested from Google Trends or Global Breaking Wires,
    automatically classifies its true `sub_pillar` and `core_hub` from the headline and summary
    so a Cricket ('Brydon Carse') or NBA ('Celtics') story NEVER gets stamped as 'AI_ROBOTICS'
    ('AI & SILICON FRONTIER') and NEVER receives semiconductor chapters!
    """
    comb_low = f"{title} {summary}".lower()
    if any(sk in comb_low for sk in [
        "cricket", "test cricket", "ipl", "bcci", "england lion", "brydon carse", "shoaib bashir", "ben stokes",
        "kohli", "rohit", "bumrah", "ashes", "wicket", "bowler", "batsman", "inning",
        "nba", "celtics", "lakers", "warriors", "bucks", "knicks", "tatum", "queta", "lebron", "curry", "basketball",
        "nfl", "super bowl", "jaguars", "eagles", "chiefs", "cowboys", "quarterback", "touchdown",
        "tennis", "wta", "atp", "coco gauff", "pegula", "swiatek", "sabalenka", "alcaraz", "sinner", "djokovic",
        "wimbledon", "indian wells", "us open", "roland garros", "australian open",
        "premier league", "champions league", "real madrid", "manchester united", "barcelona", "arsenal", "liverpool",
        "mourinho", "guardiola", "football", "soccer", "fifa", "world cup",
        "motogp", "moto3", "moto2", "marquez", "bagnaia", "bezzecchi", "formula 1", "f1", "verstappen", "hamilton",
        "ufc", "boxing", "badminton", "bwf", "chess", "fide", "olympic"
    ]):
        return "VIRAL_UNDERDOG_SPORTS", "VIRAL_UNDERDOG_SPORTS"

    if any(tk in comb_low for tk in [
        "openai", "chatgpt", "nvidia", "tsmc", "asml", "semiconductor", "silicon wafer", "gpu", "artificial intelligence",
        "deepmind", "gemini", "claude", "anthropic", "quantum computer", "robotics", "humanoid robot", "cyberattack", "ransomware"
    ]):
        return "AI_ROBOTICS", "TECHNOLOGY"

    if any(bk in comb_low for bk in [
        "stock market", "sensex", "nifty", "wall street", "nasdaq", "s&p 500", "dow jones", "ipo ", "rbi ",
        "federal reserve", "interest rate", "inflation", "gdp", "hsbc", "citigroup", "goldman sachs", "jpmorgan",
        "morgan stanley", "blackrock", "quarterly earnings", "q1 ", "q2 ", "q3 ", "q4 ", "central bank"
    ]):
        return "STOCK_MARKETS", "BUSINESS"

    if any(spk in comb_low for spk in [
        "nasa", "isro", "spacex", "starship", "james webb", "hubble", "supercluster", "galaxy", "exoplanet",
        "asteroid", "lunar", "mars rover", "space station", "cern", "nuclear fusion"
    ]):
        return "SCIENCE", "SCIENCE"

    if any(gk in comb_low for gk in [
        "missile", "airstrike", "nato", "pentagon", "sanctions", "ceasefire", "kremlin", "white house",
        "prime minister", "president", "parliament", "summit", "warship", "aircraft carrier", "fighter jet", "strait"
    ]):
        if any(ik in comb_low for ik in ["india", "new delhi", "modi", "jaishankar", "indian"]):
            return "INDIA_TRENDING", "WORLD"
        return "GEOPOLITICS", "WORLD"

    return requested_sub_pillar, PILLAR_TO_CORE_HUB.get(requested_sub_pillar, "WORLD")

def discover_dossier_for_pillar(sub_pillar, hist_obj, winning_keywords, batch_fingerprints):
    """
    100% LATEST & TRENDING 24-HOUR NEWS HARVESTER:
    Prioritizes stories published in the last 24 hours (`recency_boost`) and expands facts
    via Bing News Live RSS so every single video covers today's hottest topics!
    """
    core_hub = PILLAR_TO_CORE_HUB.get(sub_pillar, sub_pillar)
    p_cfg = CATEGORY_FEEDS.get(core_hub, CATEGORY_FEEDS["WORLD"])
    candidates = []

    base_cat_feeds = list(p_cfg["feeds"])
    country_viral_feeds = build_dynamic_country_viral_feeds(hist_obj, count_countries=6, sub_pillar=sub_pillar)
    # V63 REAL-TIME TRENDING SURGE PRIORITY: Always check live Google Trends (`IN`, `US`, `GB`) + Top 6h Breaking Wires FIRST!
    priority_trending_feeds = [
        ("Global Breaking Surge <6h (Reuters/AP/BBC/CNBC/Bloomberg)", "https://news.google.com/rss/search?q=(when:6h)+(source:Reuters+OR+source:Associated_Press+OR+source:BBC+OR+source:CNBC+OR+source:Bloomberg)&hl=en-US&gl=US&ceid=US:en"),
        ("Global Geopolitics, Economy & Tech Top 24h", "https://news.google.com/rss/headlines/section/topic/WORLD?hl=en-US&gl=US&ceid=US:en"),
        ("Google Trends USA Viral 24h", "https://trends.google.com/trending/rss?geo=US"),
        ("Google Trends UK & Europe Viral 24h", "https://trends.google.com/trending/rss?geo=GB"),
    ]
    feed_list = list(priority_trending_feeds)
    max_len_f = max(len(base_cat_feeds), len(country_viral_feeds))
    for f_i in range(max_len_f):
        if f_i < len(base_cat_feeds):
            feed_list.append(base_cat_feeds[f_i])
        if f_i < len(country_viral_feeds):
            feed_list.append(country_viral_feeds[f_i])

    for src, url in feed_list:
        try:
            r_feed = requests.get(url, headers=HEADERS_WEB, timeout=8)
            if r_feed.status_code != 200:
                continue
            feed = feedparser.parse(r_feed.content)
        except Exception:
            continue

        for entry in feed.entries[:14]:
            # Support Google Trends 100K-200K+ RSS items (extracting the viral news headline & traffic volume!)
            viral_traffic_boost = 0
            raw_t = getattr(entry, "title", "").rsplit(" - ", 1)[0]
            if "trends.google.com" in url:
                raw_xml_entry = str(entry)
                tr_m = re.search(r"([0-9,]+)\+", str(getattr(entry, "ht_approx_traffic", "") or raw_xml_entry))
                if tr_m:
                    tr_num = int(tr_m.group(1).replace(",", ""))
                    if tr_num >= 100000:
                        viral_traffic_boost = 185
                    elif tr_num >= 50000:
                        viral_traffic_boost = 135
                    else:
                        viral_traffic_boost = 95
                else:
                    viral_traffic_boost = 90
                nt_m = getattr(entry, "ht_news_item_title", "")
                if nt_m:
                    raw_t = BeautifulSoup(str(nt_m), "html.parser").get_text(" ").rsplit(" - ", 1)[0]
                elif len(raw_t.split()) < 5:
                    # Query Bing News RSS live for the short Google Trends keyword (`raw_t`) to get the exact breaking headline!
                    try:
                        gt_kw = raw_t.strip()
                        r_gt_b = requests.get(f"https://www.bing.com/news/search?q={urllib.parse.quote(gt_kw)}&format=rss", headers=HEADERS_WEB, timeout=4.0)
                        if r_gt_b.status_code == 200:
                            bf_gt = feedparser.parse(r_gt_b.content)
                            if bf_gt.entries:
                                cand_gt_h = clean_fact(getattr(bf_gt.entries[0], "title", "").rsplit(" - ", 1)[0])
                                if len(cand_gt_h.split()) >= 5:
                                    raw_t = cand_gt_h
                    except Exception:
                        pass
            low_raw_t = raw_t.lower()
            if any(bt in low_raw_t for bt in BANNED_ARTICLE_TITLES) or any(bw in low_raw_t for bw in LOW_INTEREST_BORING_WORDS):
                continue

            raw_pub = getattr(entry, "published", "") or getattr(entry, "updated", "")
            is_fresh, hours_old = is_article_fresh_last_48h(raw_pub)
            if not is_fresh:
                continue

            title = clean_fact(raw_t)
            # Strip multi-topic roundup tails (e.g. 'South Africa votes in municipal elections as Ethiopia expels diplomats')
            for split_conj in [" as ", " while ", " — and ", "; "]:
                if split_conj in title and len(title.split(split_conj)[0].strip()) >= 28:
                    left_p, right_p = title.split(split_conj, 1)
                    if has_foreign_country_collision(right_p.lower(), left_p.lower()):
                        title = left_p.strip()
                        break
            if len(title) < 24:
                continue

            link = getattr(entry, "link", "").strip()
            if any(b_url in link.lower() for b_url in ["aljazeera", "/deals/", "/shopping/", "/coupons/", "/reviews/", "/podcasts/", "/video/", "/music/"]) or "al jazeera" in getattr(entry, "title", "").lower():
                continue

            pub_date = normalize_pub_date(raw_pub)
            if not link:
                continue

            raw_sum = BeautifulSoup(getattr(entry, "summary", ""), "html.parser").get_text(separator=" ")
            summary = clean_fact(raw_sum)

            dup_status, prev_evt_title = check_semantic_duplicate_or_update(title, summary, hist_obj)
            if dup_status == "DUPLICATE":
                continue
            is_followup = (dup_status == "FOLLOWUP_UPDATE")

            cur_fp_set = set(extract_event_fingerprint(title, summary))
            if any((len(cur_fp_set.intersection(bfp)) >= 2 or (len(cur_fp_set.intersection(bfp)) / float(max(1, min(len(cur_fp_set), len(bfp)))) >= 0.22)) for bfp in batch_fingerprints):
                continue

            # V55 2-to-3 Letter Acronym & Proper Subject Lock (Prevents 'BMW' from being dropped by {4,} regex!):
            generic_geo_words = {c.lower() for c in COUNTRY_GEO_DB.keys()} | set(DEMONYM_TO_COUNTRY.keys()) | {"the", "and", "for", "with", "from", "that", "this", "news", "court", "police", "government"}
            headline_acronyms = {
                m.group(1).lower() for m in re.finditer(r"\b([A-Z0-9]{2,4})\b", title)
                if m.group(1).upper() not in {"WHY", "HOW", "THE", "AND", "FOR", "NEW", "TOP", "NOW", "Q1", "Q2", "Q3", "Q4"}
            }
            headline_specific_tokens = headline_acronyms | {
                w.lower() for w in re.findall(r"[A-Za-z0-9]{3,}", title)
                if w.lower() not in HEADLINE_STOP_VERBS_ADJS and w.lower() not in generic_geo_words and w.lower() not in {"the", "and", "for", "with", "from", "are", "was", "were", "has", "had", "not", "but", "its", "his", "her", "who", "out", "off", "now"}
            }
            primary_entity_must_toks = headline_acronyms | {
                w.lower() for w in re.findall(r"\b[A-Z][a-zA-Z0-9\-]{2,}\b", title)
                if w.lower() not in HEADLINE_STOP_VERBS_ADJS and w.lower() not in generic_geo_words and w.upper() not in {"WHY", "HOW", "THE", "Q1", "Q2", "Q3", "Q4"}
            }
            core_topic_tokens = headline_specific_tokens or {
                w.lower() for w in re.findall(r"[A-Za-z0-9]{3,}", f"{title} {summary}")
                if w.lower() not in HEADLINE_STOP_VERBS_ADJS
            }

            rss_img = None
            if hasattr(entry, "media_thumbnail") and entry.media_thumbnail:
                rss_img = entry.media_thumbnail[0].get("url")
                if rss_img and "bbci.co.uk" in rss_img:
                    rss_img = re.sub(r"/standard/\d+/", "/standard/1024/", rss_img)
            elif hasattr(entry, "media_content") and entry.media_content:
                rss_img = entry.media_content[0].get("url")

            og_img = None
            article_inline_images = []
            article_video_urls = []
            verified_claims = []

            for s in split_into_complete_sentences(summary):
                cs = clean_fact(s)
                if 40 <= len(cs) <= 200 and not is_semantically_similar_claim(cs, verified_claims, headline_title=title):
                    if cs[-1] not in ".!?":
                        cs += "."
                    verified_claims.append({
                        "text": cs,
                        "source_url": link,
                        "source_name": src,
                        "published_date": pub_date
                    })

            resolved_pub_link = resolve_google_or_bing_redirect_url(link, headline_title=title)
            if resolved_pub_link and "news.google.com" not in resolved_pub_link:
                try:
                    r = requests.get(resolved_pub_link, headers=HEADERS_WEB, timeout=6)
                    if r.status_code == 200 and "permission to access" not in r.text.lower() and "visiting is protected" not in r.text.lower():
                        soup = BeautifulSoup(r.text, "html.parser")
                        m_og = soup.find("meta", property="og:image") or soup.find("meta", attrs={"name": "twitter:image"})
                        if m_og and m_og.get("content"):
                            og_img = m_og["content"]
                            article_inline_images.append(og_img)

                        # Remove related-links, shopping, affiliate, ad & sidebar promo blocks FIRST (before scraping images or text!)
                        for bad_div in soup.find_all(["div", "section", "ul", "aside", "footer", "nav"], attrs={"class": re.compile(r"related|promo|links|more|sidebar|recommend|most-read|card|shop|commerce|affiliate|product|sponsor|outbrain|taboola|ad-", re.I)}):
                            bad_div.decompose()

                        # Harvest inline high-res article photos ONLY from inside <figure>/<article> with non-shopping alt/caption!
                        for fig_tag in soup.find_all(["figure", "article"])[:6]:
                            for img_tag in fig_tag.find_all("img")[:3]:
                                im_src = img_tag.get("src") or img_tag.get("data-src") or ""
                                im_alt = (img_tag.get("alt") or "").strip()
                                if len(im_alt) < 12 or any(bw in im_alt.lower() for bw in BANNED_CAPTION_AND_TITLE_WORDS):
                                    continue
                                if im_src.startswith("https://") and any(ext in im_src.lower() for ext in [".jpg", ".jpeg", ".png", ".webp"]):
                                    if not any(b in im_src.lower() for b in BANNED_IMAGE_SOURCES + ["icon", "logo", "avatar", "sprite", "1x1", "pixel", "shop", "product", "commerce"]):
                                        if "bbci.co.uk" in im_src:
                                            im_src = re.sub(r"/standard/\d+/", "/standard/1024/", im_src)
                                        if im_src not in article_inline_images:
                                            article_inline_images.append(im_src)

                        for m_vid in re.findall(r"(https?://[^\s\"'<>]+?\.(?:mp4|webm))", r.text, flags=re.I):
                            if not any(b in m_vid.lower() for b in ["ad", "tracker", "pixel", "logo"]) and m_vid not in article_video_urls:
                                article_video_urls.append(m_vid)

                        for p in soup.find_all("p"):
                            if p.find_parent("figcaption") or p.find_parent("figure") or p.find_parent("footer") or p.find_parent("aside") or p.find_parent("form") or p.find_parent("nav") or p.find_parent("li"):
                                continue
                            if p.find("a") and len(p.find("a").get_text(strip=True)) >= int(len(p.get_text(strip=True)) * 0.75):
                                # Skip standalone hyperlink promo lines (e.g. 'AI SpongeBob parody draws scrutiny')!
                                continue
                            p_txt = p.get_text(separator=" ").strip()
                            if any(stop_m in p_txt.lower() for stop_m in ["when you purchase through links", "earn a small commission", "related articles", "more from techcrunch", "recommended for you", "more on this story"]):
                                break
                            for rs in split_into_complete_sentences(p_txt):
                                cs = clean_fact(rs)
                                if 45 <= len(cs) <= 210 and is_claim_strictly_on_topic(cs, core_topic_tokens, headline_str=title) and not is_semantically_similar_claim(cs, verified_claims, headline_title=title):
                                    if cs[-1] not in ".!?":
                                        cs += "."
                                    verified_claims.append({
                                        "text": cs,
                                        "source_url": link,
                                        "source_name": src,
                                        "published_date": pub_date
                                    })
                                    if len(verified_claims) >= 16:
                                        break
                            if len(verified_claims) >= 16:
                                break
                except Exception:
                    pass

            if len(verified_claims) < 10:
                try:
                    # V55: Include 2-3 letter acronyms (e.g. BMW, BYD, AI, UN, IDF) in Bing News expansion query and require primary entity match!
                    all_title_toks = [
                        w for w in re.findall(r"\b(?:[A-Z0-9]{2,3}|[A-Za-z0-9\-]{4,})\b", title)
                        if w.lower() not in HEADLINE_STOP_VERBS_ADJS and w.upper() not in {"WHY", "HOW", "THE", "AND", "FOR", "Q1", "Q2", "Q3", "Q4"}
                    ]
                    geo_anchor_toks = {w.lower() for w in all_title_toks if w.lower() in generic_geo_words and w.lower() not in {"the", "and", "for", "with", "from", "that", "this", "news", "court", "police", "government"}}
                    kw_q = " ".join(all_title_toks[:6])
                    if kw_q:
                        b_rss = f"https://www.bing.com/news/search?q={urllib.parse.quote(kw_q)}&format=rss"
                        br = requests.get(b_rss, headers=HEADERS_WEB, timeout=6)
                        b_feed = feedparser.parse(br.content)
                        for b_ent in b_feed.entries[:10]:
                            ent_t_low = getattr(b_ent, "title", "").lower()
                            if primary_entity_must_toks and not any(pt in ent_t_low for pt in primary_entity_must_toks):
                                continue
                            if geo_anchor_toks and not any(gt in ent_t_low for gt in geo_anchor_toks):
                                continue
                            # V58: Extract direct publisher article URL & 1080p og:image from corroborating news articles!
                            try:
                                b_raw_link = getattr(b_ent, "link", "")
                                b_pub_url = resolve_google_or_bing_redirect_url(b_raw_link)
                                if b_pub_url and b_pub_url.startswith("https://") and len(article_inline_images) < 10 and not any(b in b_pub_url.lower() for b in ["aljazeera", "news.google.com", "bing.com"]):
                                    rb_art = requests.get(b_pub_url, headers=HEADERS_WEB, timeout=3.2)
                                    if rb_art.status_code == 200:
                                        m_og_b = re.search(r'<meta[^>]+(?:property|name)=["\'](?:og:image|twitter:image)["\'][^>]+content=["\'](https://[^"\']+)["\']', rb_art.text, flags=re.I)
                                        if not m_og_b:
                                            m_og_b = re.search(r'<meta[^>]+content=["\'](https://[^"\']+)["\'][^>]+(?:property|name)=["\'](?:og:image|twitter:image)["\']', rb_art.text, flags=re.I)
                                        if m_og_b:
                                            og_u_b = m_og_b.group(1).replace("&amp;", "&")
                                            if og_u_b not in article_inline_images and not any(b in og_u_b.lower() for b in BANNED_IMAGE_SOURCES + ["logo", "icon", "avatar"]):
                                                article_inline_images.append(og_u_b)
                                        for mv_b in re.findall(r'(https?://[^\s"\'<>]+?\.mp4)', rb_art.text, flags=re.I)[:2]:
                                            if mv_b not in article_video_urls and not any(b in mv_b.lower() for b in ["ad", "logo", "pixel"]):
                                                article_video_urls.append(mv_b)
                            except Exception:
                                pass
                            b_desc = clean_fact(BeautifulSoup(getattr(b_ent, "summary", ""), "html.parser").get_text(separator=" "))
                            for bs in split_into_complete_sentences(b_desc):
                                cbs = clean_fact(bs)
                                s_toks = {w.lower() for w in re.findall(r"[A-Za-z0-9\-]{4,}", cbs)}
                                if geo_anchor_toks and not any(gt in cbs.lower() for gt in geo_anchor_toks) and len(s_toks.intersection(headline_specific_tokens)) < 2:
                                    continue
                                if 40 <= len(cbs) <= 215 and len(s_toks.intersection(core_topic_tokens)) >= 1 and not is_semantically_similar_claim(cbs, verified_claims, headline_title=title):
                                    if cbs[-1] not in ".!?":
                                        cbs += "."
                                    verified_claims.append({
                                        "text": cbs,
                                        "source_url": link,
                                        "source_name": src,
                                        "published_date": pub_date
                                    })
                                    if len(verified_claims) >= 16:
                                        break
                            # Also harvest the corroborating headline + source if it adds new specifics
                            b_title_clean = clean_fact(getattr(b_ent, "title", "").rsplit(" - ", 1)[0])
                            if 42 <= len(b_title_clean) <= 195 and not is_semantically_similar_claim(b_title_clean, verified_claims, headline_title=title):
                                b_toks = {w.lower() for w in re.findall(r"[A-Za-z0-9\-]{4,}", b_title_clean)}
                                if len(b_toks.intersection(core_topic_tokens)) >= 1:
                                    verified_claims.append({
                                        "text": b_title_clean if b_title_clean[-1] in ".!?" else f"{b_title_clean}.",
                                        "source_url": link,
                                        "source_name": src,
                                        "published_date": pub_date
                                    })
                except Exception:
                    pass

            if len(verified_claims) < 4:
                try:
                    from ddgs import DDGS
                    all_title_toks = [w for w in re.findall(r"[A-Za-z0-9\-]{4,}", title) if w.lower() not in HEADLINE_STOP_VERBS_ADJS]
                    kw_q = " ".join(all_title_toks[:6])
                    if kw_q:
                        with DDGS() as ddgs:
                            for d_item in list(ddgs.news(kw_q, max_results=6)):
                                d_body = clean_fact(f"{d_item.get('title', '')}. {d_item.get('body', '')}")
                                for ds in split_into_complete_sentences(d_body):
                                    cds = clean_fact(ds)
                                    s_toks = {w.lower() for w in re.findall(r"[A-Za-z0-9\-]{4,}", cds)}
                                    if 40 <= len(cds) <= 215 and len(s_toks.intersection(core_topic_tokens)) >= 1 and not is_semantically_similar_claim(cds, verified_claims, headline_title=title):
                                        verified_claims.append({
                                            "text": cds if cds[-1] in ".!?" else f"{cds}.",
                                            "source_url": d_item.get("url") or link,
                                            "source_name": d_item.get("source") or src,
                                            "published_date": pub_date
                                        })
                                        if len(verified_claims) >= 12:
                                            break
                except Exception:
                    pass

            if len(verified_claims) < 2:
                continue

            raw_facts = [c["text"] for c in verified_claims]
            true_sub_p, true_core_h = auto_detect_true_sub_pillar_and_hub_v64(title, " ".join(raw_facts[:3]), sub_pillar)
            p_cfg_item = CATEGORY_FEEDS.get(true_core_h, p_cfg)
            c_prof = resolve_country_or_domain_profile(title, raw_facts, pillar_name=true_core_h)
            mood_cat = classify_story_mood_and_category(title, " ".join(raw_facts[:4]), pillar_name=true_core_h)

            temp_d = {"title": title, "raw_facts": raw_facts, "country_profile": c_prof, "pillar": true_core_h, "sub_pillar": true_sub_p}
            t_anchor = extract_primary_topic_anchor(temp_d)
            orig_yt_title = build_100_percent_original_youtube_title(title, true_sub_p, c_prof, t_anchor, is_update=is_followup)

            comb = f"{title} {' '.join(raw_facts[:3])}".lower()
            country_name_upper = c_prof.get("name", "INTERNATIONAL").upper()
            last_countries = hist_obj.get("last_countries", [])

            # 1. V63 VIRAL TRENDING FIRST PRIORITY (Removed the -650 country blocker that killed US/India/China breaking news!):
            # Only apply a mild tie-breaker (-35) if the exact same country was in the immediately preceding upload,
            # AND give a +110 High-Search-Demand Boost to major global power hubs (USA, INDIA, CHINA, RUSSIA, ISRAEL, UK, IRAN, TAIWAN, JAPAN)!
            # V67 TRUE ALL-WORLD GLOBAL COUNTRY ROTATION (Covers all 46+ countries worldwide without repeating the last 4 countries!):
            if country_name_upper in last_countries[-2:]:
                country_penalty = 280
            elif country_name_upper in last_countries[-5:]:
                country_penalty = 140
            else:
                country_penalty = 0
            major_demand_boost = 75 if country_name_upper != "INTERNATIONAL" else 35

            # 2. Equal Global Country Boost + Massive 100K-200K+ Viral Traffic Boost + V45 44K-View Underdog Prodigy Boost!
            tier_boost = 30 if country_name_upper != "INTERNATIONAL" else 5
            underdog_viral_boost = 0
            if any(ukw in comb for ukw in ["year-old", "16-year-old", "17-year-old", "18-year-old", "19-year-old", "teen", "teenager", "prodigy", "rookie", "youngest", "underdog", "moto3", "motogp", "grandmaster", "upset", "stunned"]):
                underdog_viral_boost += 95
            if country_name_upper in {"INDONESIA", "INDIA", "PHILIPPINES", "BRAZIL", "MALAYSIA", "VIETNAM", "THAILAND", "TURKEY", "MEXICO", "PAKISTAN", "BANGLADESH", "NIGERIA", "EGYPT", "SOUTH AFRICA", "KENYA"}:
                underdog_viral_boost += 55
            tier_boost += underdog_viral_boost
            high_impact_kws = ["war", "military", "missile", "president", "prime minister", "parliament", "sanctions", "crisis", "billion", "trillion", "protest", "strike", "supreme court", "breakthrough", "nuclear", "treaty", "summit", "collapse", "intelligence", "tariffs", "arrest"]
            impact_boost = sum(12 for hkw in high_impact_kws if hkw in comb)

            analytics_boost = sum(10 for w_kw in winning_keywords if re.search(rf"\b{re.escape(w_kw)}\b", comb))
            recency_boost = int(max(0.0, 48.0 - hours_old) * 2.5)
            update_boost = 25 if is_followup else 0
            # V63 Ultra-Fresh < 6h Breaking News Surge Bonus (+120 pts for news under 6 hours old!)
            breaking_6h_bonus = 120 if hours_old <= 6.0 else (65 if hours_old <= 12.0 else 0)
            trend_score = (len(verified_claims) * 4) + viral_traffic_boost + impact_boost + analytics_boost + recency_boost + breaking_6h_bonus + major_demand_boost + update_boost + tier_boost - country_penalty

            candidates.append({
                "score": trend_score,
                "pillar": true_core_h,
                "sub_pillar": true_sub_p,
                "yt_category_id": p_cfg_item["yt_category_id"],
                "story_key": make_story_key(title),
                "event_tokens": list(cur_fp_set),
                "is_followup_update": is_followup,
                "previous_event_title": prev_evt_title,
                "title": title,
                "original_yt_title": orig_yt_title,
                "topic_anchor": t_anchor,
                "article_inline_images": article_inline_images[:8],
                "article_video_urls": article_video_urls[:4],
                "category": mood_cat,
                "source_url": link,
                "published_date": pub_date,
                "source_name": src,
                "verified_claims": verified_claims,
                "raw_facts": raw_facts,
                "lead_img": og_img or rss_img,
                "wiki_gallery_urls": [],
                "country_profile": c_prof,
                "wb_data": None
            })
            # Cap at max 2 candidates per single feed so we ALWAYS sample across BBC, USA, India, Israel/UAE, Europe, Asia & Global feeds!
            if sum(1 for c_it in candidates if c_it["source_name"] == src) >= 2:
                break
        if len(candidates) >= 28:
            break

    if not candidates:
        return None
    candidates.sort(key=lambda x: x["score"], reverse=True)
    chosen = candidates[0]
    chosen_country = chosen["country_profile"].get("name", "INTERNATIONAL").upper()
    hist_obj.setdefault("last_countries", []).append(chosen_country)
    print(
        f"🌍 [Global Country & Public Demand Audit] Selected Country: {chosen_country} | "
        f"Topic: '{chosen['title'][:52]}' | Score: {chosen['score']} (Pool Audited: {len(candidates)} Global Stories)",
        flush=True
    )
    batch_fingerprints.append(set(chosen["event_tokens"]))
    return chosen

def build_daily_24h_mega_news_dossier():
    print("\n:: [USA 6:00 PM MEGA-BROADCAST] Harvesting Top 24-Hour Breaking News Across the Globe...", flush=True)
    mega_claims = []
    visual_anchors = []
    lead_img = None
    pub_d = datetime.utcnow().strftime("%Y-%m-%d")

    # Prioritize direct full-text global wire feeds first so we get rich article paragraphs without Google News duplicate titles
    feed_sources = [
        ("BBC World Breaking", "http://feeds.bbci.co.uk/news/world/rss.xml"),
                ("The Guardian World", "https://www.theguardian.com/world/rss"),
        ("DW World News", "https://rss.dw.com/rdf/rss-en-world"),
        ("France24 World", "https://www.france24.com/en/rss"),
        ("CNBC Business", "https://search.cnbc.com/rs/search/combinedcms/view.xml?partnerId=wrss01&id=10001147"),
        ("BBC Technology", "http://feeds.bbci.co.uk/news/technology/rss.xml"),
        ("Space.com Breaking", "https://www.space.com/feeds/all"),
        ("Google News World 24h", "https://news.google.com/rss/headlines/section/topic/WORLD?hl=en-US&gl=US&ceid=US:en")
    ]

    for src, url in feed_sources:
        try:
            r = requests.get(url, headers=HEADERS_WEB, timeout=8)
            if r.status_code != 200:
                continue
            feed = feedparser.parse(r.content)
            for entry in feed.entries[:6]:
                raw_t = clean_fact(entry.title.rsplit(" - ", 1)[0])
                if len(raw_t) < 25 or any(bt in raw_t.lower() for bt in BANNED_ARTICLE_TITLES):
                    continue
                soup_sum = BeautifulSoup(getattr(entry, "summary", ""), "html.parser")
                # If Google News list of links, take only distinct sub-headlines that don't repeat raw_t
                li_texts = [clean_fact(li.get_text(" ").rsplit(" - ", 1)[0]) for li in soup_sum.find_all("li")]
                extra_sents = []
                for lt in li_texts:
                    if len(lt) > 30 and lt.lower()[:25] != raw_t.lower()[:25]:
                        extra_sents.append(lt.rstrip(".") + ".")
                if not extra_sents:
                    raw_sum = clean_fact(soup_sum.get_text(separator=" "))
                    if raw_sum and raw_sum.lower()[:25] != raw_t.lower()[:25]:
                        extra_sents.append(raw_sum.rstrip(".") + ".")

                link = getattr(entry, "link", "https://news.google.com")
                if "news.google.com" not in link and len(extra_sents) < 2:
                    try:
                        ar = requests.get(link, headers=HEADERS_WEB, timeout=5)
                        if ar.status_code == 200:
                            asoup = BeautifulSoup(ar.text, "html.parser")
                            for p in asoup.find_all("p")[:6]:
                                pt = clean_fact(p.get_text(" ").strip())
                                if 45 <= len(pt) <= 190 and pt.lower()[:25] != raw_t.lower()[:25]:
                                    extra_sents.append(pt.rstrip(".") + ".")
                                    if len(extra_sents) >= 2:
                                        break
                    except Exception:
                        pass

                body_joined = " ".join(extra_sents[:2])
                combined_txt = f"{raw_t.rstrip('.')}. {body_joined}".strip() if body_joined else f"{raw_t.rstrip('.')}."
                if not is_semantically_similar_claim(combined_txt, mega_claims):
                    mega_claims.append({
                        "text": combined_txt[:340],
                        "headline_short": raw_t[:65],
                        "source_url": link,
                        "source_name": src,
                        "published_date": pub_d
                    })
                    words_ent = [w for w in re.findall(r"[A-Za-z]{4,}", raw_t) if w.lower() not in HEADLINE_STOP_VERBS_ADJS]
                    if words_ent:
                        visual_anchors.append(" ".join(words_ent[:3]))
                    if not lead_img and hasattr(entry, "media_thumbnail") and entry.media_thumbnail:
                        lead_img = entry.media_thumbnail[0].get("url")
                if len(mega_claims) >= 18:
                    break
        except Exception:
            pass
        if len(mega_claims) >= 18:
            break

    if len(mega_claims) < 8:
        return None

    date_label = datetime.utcnow().strftime("%B %d, %Y")
    mega_title = f"24 Hours in 10 Minutes: Global Geopolitics & World News Briefing ({date_label})"
    c_prof = build_country_dict_from_db("UNITED STATES", is_global_topic=False)

    return {
        "score": 9999,
        "pillar": "WORLD",
        "sub_pillar": "DAILY_24H_MEGA_NEWS",
        "is_mega_24h": True,
        "yt_category_id": "25",
        "story_key": f"mega_24h_{datetime.utcnow().strftime('%Y_%m_%d')}",
        "event_tokens": ["global", "briefing", "24h", datetime.utcnow().strftime("%Y%m%d")],
        "is_followup_update": False,
        "previous_event_title": None,
        "title": mega_title,
        "original_yt_title": mega_title[:95],
        "topic_anchor": "Global Geopolitics Summit",
        "visual_anchors": visual_anchors[:15] if visual_anchors else ["United Nations", "White House", "Pentagon", "Wall Street"],
        "article_video_urls": [],
        "category": "dark_geopolitics",
        "source_url": "https://news.google.com",
        "published_date": pub_d,
        "source_name": "Global Wire Services",
        "verified_claims": mega_claims,
        "raw_facts": [c["text"] for c in mega_claims],
        "lead_img": lead_img,
        "wiki_gallery_urls": [],
        "country_profile": c_prof,
        "wb_data": None
    }

