def has_foreign_country_collision(text_low, story_context_low):
    """
    Returns True if `text_low` mentions a country, demonym, leader, or major city (e.g. 'Trump', 'Vance',
    'Delhi', 'Pachaiyappa', 'Malaysia', 'The Edge TV', 'Subic') that is NOT part of `story_context_low`!
    """
    for group_terms in FOREIGN_PLACE_COLLISION_TERMS:
        # If the story itself is about this country group, skip checking it
        if any(gt in story_context_low for gt in group_terms[:6]):
            continue
        for term in group_terms:
            if re.search(rf"\b{re.escape(term)}\b", text_low):
                return True
    return False

def synthesize_3d_parallax_broadcast_video_broll(pil_im, tag_id="parallax_vclip", caption_str="HD DOCUMENTARY FOOTAGE", motion_idx=0):
    """
    V36 GUARANTEED 1080p 3D PARALLAX CINEMA MOTION B-ROLL GENERATOR:
    When external video hosts (YouTube/Dailymotion) throttle a GitHub Actions runner IP,
    converts a verified 1080p HD documentary press photo into a smooth 6.5-second 1080p MP4
    3D multi-plane parallax motion clip (separating foreground & background planes with optical
    depth blur, smooth 3D camera dolly + pan + subtle broadcast lens sweep) so every chapter
    ALWAYS has rich moving 1080p video B-roll!
    """
    try:
        out_mp4 = f"temp/{tag_id}_3dparallax.mp4"
        base_rgb = pil_im.convert("RGB")
        resample_m = getattr(Image, "Resampling", Image).LANCZOS
        over_w, over_h = 2240, 1260
        fg_im = fit_full_height_face_aware_1080p(base_rgb, over_w, over_h)
        bg_im = fg_im.filter(ImageFilter.GaussianBlur(radius=14))
        bg_im = ImageEnhance.Brightness(bg_im).enhance(0.55)
        fg_arr = np.asarray(fg_im, dtype=np.float32)
        bg_arr = np.asarray(bg_im, dtype=np.float32)

        dur_s = 6.5
        fps_v = 30
        direction = 1 if (int(motion_idx) % 2 == 0) else -1

        def _make_parallax_frame(t):
            p = min(max(t / dur_s, 0.0), 1.0)
            # Smooth cosine easing
            ease_p = 0.5 - 0.5 * math.cos(math.pi * p)
            # Background plane moves slower (0.45x parallax), foreground moves faster (1.0x)
            bg_dx = int((over_w - 1920) * 0.5 + direction * 55 * (ease_p - 0.5))
            bg_dy = int((over_h - 1080) * 0.5 + 24 * (ease_p - 0.5))
            bg_crop = bg_arr[bg_dy:bg_dy + 1080, bg_dx:bg_dx + 1920]

            fg_dx = int((over_w - 1920) * 0.5 - direction * 110 * (ease_p - 0.5))
            fg_dy = int((over_h - 1080) * 0.5 - 42 * (ease_p - 0.5))
            fg_crop = fg_arr[fg_dy:fg_dy + 1080, fg_dx:fg_dx + 1920]

            # Soft radial vignette blend between crisp foreground subject and deep parallax periphery
            out = (fg_crop * 0.88 + bg_crop * 0.12).clip(0, 255).astype(np.uint8)
            return out

        vc = VideoClip(_make_parallax_frame, duration=dur_s)
        vc = vc.with_fps(fps_v) if MOVIEPY_V2 else vc.set_fps(fps_v)
        vc.write_videofile(
            out_mp4, fps=fps_v, codec="libx264", audio=False,
            preset="ultrafast", threads=2, logger=None
        )
        vc.close()
        if os.path.exists(out_mp4) and os.path.getsize(out_mp4) > 25000:
            loaded_vc = VideoFileClip(out_mp4)
            GLOBAL_OPEN_VCLIPS.append(loaded_vc)
            return {"vclip": loaded_vc, "path": out_mp4, "source_query": caption_str[:42], "is_parallax": True}
    except Exception:
        pass
    return None

def fetch_and_transcode_real_video_broll(video_query, dossier, used_video_urls, used_video_queries, tag_id="vclip"):
    """
    V36 5-ENGINE BULLETPROOF HD VIDEO & INTERVIEW HARVESTER:
    Combines 5 independent video engines so datacenter rate-limits on any single platform NEVER stop video B-roll:
    1. Direct News Article `.mp4` streams harvested from multi-site news articles.
    2. Bing Video CDN (`th?id=OVP...` direct MP4 streams from `bing.com/videos/search` — zero `yt-dlp` needed!).
    3. Wikimedia Commons Official Video API (`commons.wikimedia.org/w/api.php` `.webm`/`.mp4` documentary/news clips — 100% datacenter-friendly!).
    4. Dailymotion Official JSON API (`api.dailymotion.com/videos`).
    5. YouTube Topic & Interview Search (`yt-dlp ytsearch5:`).
    """
    topic_anchor = str(dossier.get("topic_anchor") or extract_primary_topic_anchor(dossier)).strip()
    story_title = str(dossier.get("title", "")).strip()

    geo_anchor_tokens, event_context_tokens = get_story_anchor_and_context_tokens(dossier)
    master_queries = extract_topic_master_queries(dossier)
    query_str = video_query if (video_query and video_query.lower() not in used_video_queries) else (master_queries[0] if master_queries else topic_anchor)
    for mq in master_queries:
        if mq.lower() not in used_video_queries:
            query_str = mq
            break
    used_video_queries.add(query_str.lower())

    # 1. Direct News Article MP4 Streams + V62 NASA / Internet Archive / DVIDS Public Domain Video Streams
    for art_v in dossier.get("article_video_urls", []):
        res = download_and_transcode_mp4_url(art_v, used_video_urls, f"{tag_id}_art", query_str)
        if res is not None:
            return res
    try:
        if "harvest_v62_internet_archive_and_dvids_video_urls" in globals():
            for osint_v_url in harvest_v62_internet_archive_and_dvids_video_urls(query_str, dossier, max_clips=3):
                if osint_v_url.endswith(".mp4"):
                    res_osv = download_and_transcode_mp4_url(osint_v_url, used_video_urls, f"{tag_id}_osint", query_str)
                    if res_osv is not None:
                        return res_osv
    except Exception:
        pass

    strict_banned_video_words = [
        "zoom", "meetup", "wikimedia", "wikimania", "user group", "hangout", "jitsi", "vlog", "webcam",
        "gaming", "game", "gameplay", "counter-strike", "csgo", "valorant", "call of duty", "warzone",
        "gta", "roblox", "fortnite", "simulator", "fps", "twitch", "minecraft", "cartoon", "anime",
        "comic", "podcast", "golf", "golfer", "pga", "european tour", "dp world tour", "oman open",
        "hole 1", "hole 2", "hole 3", "hole 4", "hole 5", "hole 6", "hole 7", "hole 8", "hole 9",
        "hole 10", "hole 11", "hole 12", "hole 13", "hole 14", "hole 15", "hole 16", "hole 17", "hole 18",
        "par 3", "par 4", "par 5", "birdie", "fairway", "putt", "putting", "tee shot",
        "pronunciation", "spoken", "audio", "wikidata",
        "nude", "naked", "nsfw", "erotic", "sex", "bikini", "lingerie", "swimsuit", "anatomy", "statue",
        "webinar", "slide", "piano", "guitar", "violin", "bedroom", "kitchen", "unboxing", "voa",
        "voice of america", "noaa", "cira", "geocolor", "satellite loop", "intro", "bumper", "logo",
        "chalkboard", "blackboard", "subic", "charcuterie", "cheese board", "cowboy", "western movie",
        "the edge tv", "steamship", "shipwreck", "wreck", "sunken", "nazi", "treasure", "dancing thief",
        "thieves", "pachaiyappa", "landmarks", "places to visit", "things to do", "travel guide",
        "pagoda", "cherry blossom", "sakura", "mount fuji", "osaka castle", "waterfall",
        "salman khan", "shah rukh", "bollywood", "dispensary", "antilla", "moving to london",
        "coding contest", "school contest", "nikki haley", "tourist destination", "tourist destinations",
        "kuwait towers", "taj mahal", "scooter", "scooters", "hazmat", "thailand", "bangkok", "phuket"
    ]

    story_ctx_low = f"{story_title} {topic_anchor} {dossier.get('country_profile', {}).get('name', '')}".lower()

    # Extract strict subject nouns directly from the story headline (`story_title`) + `query_str`
    # so random words from paragraph 8 of `raw_facts` (like 'leave', 'votes', 'dive') can NEVER validate an off-topic video clip!
    headline_subj_toks = {
        w.lower() for w in re.findall(r"\b(?:[A-Z0-9]{2,3}|[A-Za-z0-9]{4,})\b", f"{story_title} {topic_anchor} {query_str}")
        if w.lower() not in HEADLINE_STOP_VERBS_ADJS
        and w.lower() not in SENTENCE_VISUAL_STOPWORDS
        and w.lower() not in geo_anchor_tokens
        and w.lower() not in {"united", "kingdom", "states", "europe", "european", "global", "world", "news", "video", "footage", "face", "after", "false", "across", "why", "how", "the", "and", "for"}
    }
    primary_anchor_toks = {
        w.lower() for w in re.findall(r"\b(?:[A-Z0-9]{2,3}|[A-Za-z0-9]{4,})\b", f"{topic_anchor} {story_title}")
        if w.lower() not in HEADLINE_STOP_VERBS_ADJS and w.lower() not in {"why", "how", "the", "and", "for", "real", "story"}
    }

    def _is_valid_video_title_for_story(v_title_str, v_url_str="", relaxed_for_commons=False):
        # Reject non-ASCII regional scripts (Devanagari/Hindi, Tamil, Kannada, Arabic, Cyrillic, etc.)
        clean_vt = re.sub(r"[\u2010-\u2027\u2030-\u205E•—–‘’“”]", " ", str(v_title_str or ""))
        if re.search(r"[^\x00-\x7F]", clean_vt):
            return False
        comb_v = f"{clean_vt} {v_url_str}".lower()
        regional_tv_ban = [
            "suno india", "aaj tak", "aajtak", "ndtv", "zee news", "abp news", "india tv", "republic world",
            "tv9", "suvarna", "public tv", "puthiya", "manorama", "mathrubhumi", "etv", "sakshi", "abn",
            "arirang", "sabc", "channels television", "ntv kenya", "ktn news",
            "full bulletin", "live bulletin", "morning news", "evening news", "reaction",
            "tiktok", "reel"
        ]
        if any(bw in comb_v for bw in strict_banned_video_words + BANNED_CAPTION_AND_TITLE_WORDS + regional_tv_ban + ["votes to leave", "brexit", "united airlines"]):
            return False
        if has_foreign_country_collision(comb_v, story_ctx_low):
            return False
        v_toks = {w.lower() for w in re.findall(r"[A-Za-z0-9]{3,}", comb_v)}
        has_geo = len(geo_anchor_tokens.intersection(v_toks)) >= 1
        subj_hits = len(headline_subj_toks.intersection(v_toks))
        ev_hits = len((event_context_tokens - {"leave", "votes", "vote", "euro", "dive", "face", "false", "after"}).intersection(v_toks))
        anchor_hits = len(primary_anchor_toks.intersection(v_toks))
        if relaxed_for_commons:
            return (anchor_hits >= 1) or (has_geo and (subj_hits >= 1 or ev_hits >= 1)) or (subj_hits >= 2)
        # V58: Accept real interview / event footage if it matches the primary topic anchor (`anchor_hits >= 1` and `subj_hits >= 1`)!
        return (subj_hits >= 2) or (anchor_hits >= 1 and (subj_hits >= 1 or ev_hits >= 1)) or (has_geo and (subj_hits >= 1 or ev_hits >= 2))

    # V53 SHORT 2-TO-4 WORD VIDEO SEARCH QUERIES (Crucial for Dailymotion, Reddit, Wikimedia & Bing Video APIs!):
    # 7-word queries return 0 results on Dailymotion/Reddit/Wikimedia AND-search; 2-to-4 word entity queries return dozens of HD clips!
    short_q_1 = " ".join(query_str.split()[:4]).strip()
    short_q_2 = " ".join(topic_anchor.split()[:3]).strip()
    c_name_v = str(dossier.get("country_profile", {}).get("name", "")).strip()
    if c_name_v.upper() in ("GLOBAL", "INTERNATIONAL", "GLOBAL BRIEFING", "GLOBAL CINEMA"):
        c_name_v = ""
    short_q_3 = f"{c_name_v} {' '.join(topic_anchor.split()[:2])}".strip() if c_name_v else short_q_2
    candidate_video_queries = []
    for cq in [short_q_1, short_q_2, f"{short_q_2} interview speech", f"{short_q_2} raw footage", short_q_3, f"{short_q_2} news", query_str[:42]]:
        cq_clean = " ".join(cq.split()).strip()
        if cq_clean and len(cq_clean) >= 4 and cq_clean.lower() not in [x.lower() for x in candidate_video_queries]:
            candidate_video_queries.append(cq_clean)

    # 2. Direct High-Res `.mp4` Video Streams Only (NEVER `th?id=OVP` 300x168 blurry hover previews or news anchor studio intros!)
    for bv_q in candidate_video_queries[:2]:
        try:
            bvr = requests.get(
                f"https://www.bing.com/videos/search?q={urllib.parse.quote(bv_q + ' -cartoon -pixar -disney -movie -game -stock -arirang -anchor')}&FORM=HDRSC4",
                headers=HEADERS_WEB, timeout=5
            )
            vrhm_blocks = re.findall(r'vrhm="([^"]+)"', bvr.text)
            for vb_raw in vrhm_blocks[:10]:
                vb = vb_raw.replace("&quot;", '"').replace("&amp;", "&").replace("\\/", "/")
                vt_m = re.search(r'"vt"\s*:\s*"([^"]+)"', vb)
                v_title = vt_m.group(1) if vt_m else ""
                if not v_title or not _is_valid_video_title_for_story(v_title, vb):
                    continue
                u_m = re.search(r'(https?://[^"\s<>\\]+?\.mp4[^"\s<>\\]*)', vb)
                if u_m:
                    m_clean = u_m.group(1)
                    if m_clean not in used_video_urls and not any(b in m_clean.lower() for b in ["aljazeera", "cartoon", "game", "logo", "periscopefilm", "arirang"]):
                        res = download_and_transcode_mp4_url(m_clean, used_video_urls, f"{tag_id}_bingv", v_title[:38])
                        if res is not None:
                            return res
        except Exception:
            pass

    # 2B. Reddit Public Direct 720p/1080p MP4 Video Harvester (`v.redd.it` — Zero Datacenter Bot Block!)
    for rd_q in candidate_video_queries[:3]:
        try:
            rd_url = f"https://www.reddit.com/search.json?q={urllib.parse.quote(rd_q)}&sort=relevance&t=year&limit=14"
            rd_r = requests.get(rd_url, headers={"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) Chrome/128.0.0.0"}, timeout=5)
            if rd_r.status_code == 200:
                posts = ((rd_r.json().get("data") or {}).get("children") or [])
                for p_it in posts[:12]:
                    pdata = p_it.get("data") or {}
                    p_title = str(pdata.get("title") or "")
                    if not p_title or pdata.get("over_18") or not _is_valid_video_title_for_story(p_title, ""):
                        continue
                    rv_obj = ((pdata.get("secure_media") or {}).get("reddit_video") or (pdata.get("media") or {}).get("reddit_video") or {})
                    fb_mp4 = str(rv_obj.get("fallback_url") or "").split("?")[0]
                    if fb_mp4 and fb_mp4.endswith(".mp4") and fb_mp4 not in used_video_urls:
                        res = download_and_transcode_mp4_url(fb_mp4, used_video_urls, f"{tag_id}_redv", p_title[:38], skip_intro_sec=0.5)
                        if res is not None:
                            res["is_real_video"] = True
                            return res
        except Exception:
            pass

    # 2C. Bing Video Search `murl` / `vurl` Harvester (Extracts real YouTube/Dailymotion/Publisher video URLs via Bing!)
    for bv_q2 in candidate_video_queries[:2]:
        try:
            bvr2 = requests.get(
                f"https://www.bing.com/videos/search?q={urllib.parse.quote(bv_q2 + ' news footage speech')}&FORM=HDRSC4",
                headers=HEADERS_WEB, timeout=5
            )
            for vb_raw in re.findall(r'vrhm="([^"]+)"', bvr2.text)[:10]:
                vb = vb_raw.replace("&quot;", '"').replace("&amp;", "&").replace("\\/", "/")
                vt_m = re.search(r'"vt"\s*:\s*"([^"]+)"', vb)
                v_title = vt_m.group(1) if vt_m else ""
                if not v_title or not _is_valid_video_title_for_story(v_title, vb):
                    continue
                murl_m = re.search(r'"murl"\s*:\s*"(https?://[^"]+)"', vb) or re.search(r'"vurl"\s*:\s*"(https?://[^"]+)"', vb)
                if murl_m:
                    v_link = murl_m.group(1)
                    if v_link not in used_video_urls and ("youtube.com/watch" in v_link or "dailymotion.com/video" in v_link):
                        res = download_ytdlp_news_broll_clip(v_link, used_video_urls, f"{tag_id}_bmurl", v_title[:38])
                        if res is not None:
                            return res
        except Exception:
            pass

    # 3. Wikimedia Commons Official Video Search API (`.webm` / `.mp4` real footage — 100% immune to datacenter blocks!)
    for wc_q in candidate_video_queries[:3]:
        try:
            wc_api = (
                "https://commons.wikimedia.org/w/api.php?action=query&generator=search"
                f"&gsrsearch={urllib.parse.quote(wc_q + ' filetype:video')}&gsrnamespace=6&gsrlimit=8"
                "&prop=imageinfo&iiprop=url|size|mime|extmetadata&format=json"
            )
            wcr = requests.get(wc_api, headers=HEADERS_WIKI, timeout=5)
            if wcr.status_code == 200:
                pages = (wcr.json().get("query") or {}).get("pages") or {}
                for _, p_obj in pages.items():
                    t_title = str(p_obj.get("title") or "")
                    ii_list = p_obj.get("imageinfo") or []
                    if not ii_list:
                        continue
                    ii = ii_list[0]
                    v_url = str(ii.get("url") or "")
                    v_mime = str(ii.get("mime") or "").lower()
                    v_size = int(ii.get("size") or 0)
                    if not v_url or v_url in used_video_urls or ("video" not in v_mime and not v_url.lower().endswith((".webm", ".mp4", ".ogv"))):
                        continue
                    if v_size < 150000 or v_size > 45000000:
                        continue
                    ext_m = ii.get("extmetadata") or {}
                    desc_v = re.sub(r"<[^>]+>", " ", str((ext_m.get("ImageDescription") or {}).get("value") or ""))
                    if not _is_valid_video_title_for_story(f"{t_title} {desc_v}", v_url, relaxed_for_commons=True):
                        continue
                    res = download_and_transcode_mp4_url(v_url, used_video_urls, f"{tag_id}_wcv", t_title.replace("File:", "")[:38])
                    if res is not None:
                        return res
        except Exception:
            pass

    # 4. Dailymotion Official News & Interview API
    for dm_q in candidate_video_queries[:2]:
        try:
            dm_api = f"https://api.dailymotion.com/videos?search={urllib.parse.quote(dm_q)}&fields=id,title,url,duration,language&limit=6&longer_than=0"
            dm_r = requests.get(dm_api, headers=HEADERS_WEB, timeout=4.5)
            if dm_r.status_code == 200:
                for v_it in dm_r.json().get("list", [])[:5]:
                    v_title = str(v_it.get("title", ""))
                    v_url = str(v_it.get("url", ""))
                    v_dur = int(v_it.get("duration") or 0)
                    if not v_url or v_url in used_video_urls or v_dur < 12 or v_dur > 480:
                        continue
                    if not _is_valid_video_title_for_story(v_title, v_url):
                        continue
                    res = download_ytdlp_news_broll_clip(v_url, used_video_urls, f"{tag_id}_dm", v_title[:38])
                    if res is not None:
                        return res
        except Exception:
            pass

    # 5. YouTube Topic & Interview Search (`ytsearch5:`)
    for yt_q in candidate_video_queries[:2]:
        try:
            proc_yt = subprocess.Popen(
                [
                    "yt-dlp", "--flat-playlist", "--dump-json", "--no-warnings", "--quiet",
                    f"ytsearch5:{yt_q}"
                ],
                stdin=subprocess.DEVNULL, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL,
                start_new_session=True, text=True
            )
            out_yt, _ = proc_yt.communicate(timeout=8)
            for line_j in (out_yt or "").splitlines():
                if not line_j.strip():
                    continue
                v_meta = json.loads(line_j)
                v_id = str(v_meta.get("id") or "")
                v_title = str(v_meta.get("title") or "")
                v_dur = float(v_meta.get("duration") or 60.0)
                v_url = f"https://www.youtube.com/watch?v={v_id}" if v_id else str(v_meta.get("url") or "")
                if not v_url or v_url in used_video_urls or v_dur < 15 or v_dur > 900:
                    continue
                if not _is_valid_video_title_for_story(v_title, v_url):
                    continue
                res = download_ytdlp_news_broll_clip(v_url, used_video_urls, f"{tag_id}_yt", v_title[:40])
                if res is not None:
                    return res
        except Exception:
            try:
                os.killpg(os.getpgid(proc_yt.pid), signal.SIGKILL)
            except Exception:
                pass

    return None

# ==============================================================================
# 9. STRICT 1080p HD PHOTO VALIDATOR & CINEMA DOCUMENTARY LUT
# ==============================================================================
def apply_copyright_safe_documentary_lut(im):
    """
    V59 CONSISTENT HOLLYWOOD DOCUMENTARY SPLIT-TONE COLOR GRADE + 4K OPTICAL CLARITY LUT:
    Unifies all harvested visuals into a cohesive Netflix / Think School documentary color palette:
    - Deep Shadows tinted toward Cinema Dark Navy (`#0A1224`)
    - Midtones enriched with crisp Atomic Blue/Cyan separation
    - Highlights warmed toward Burnished Documentary Gold (`#FFD700`)
    - Zero bilateral smearing and zero HDR haloing!
    """
    try:
        arr = np.asarray(im.convert("RGB"), dtype=np.float32)
        luma = 0.299 * arr[:, :, 0] + 0.587 * arr[:, :, 1] + 0.114 * arr[:, :, 2]
        shadow_w = np.clip((95.0 - luma) / 95.0, 0.0, 1.0)
        high_w = np.clip((luma - 145.0) / 110.0, 0.0, 1.0)
        # Split-tone: Navy shadows + Warm Burnished Gold highlights
        arr[:, :, 0] = np.clip(arr[:, :, 0] - 4.5 * shadow_w + 5.5 * high_w, 0.0, 255.0)
        arr[:, :, 1] = np.clip(arr[:, :, 1] + 1.0 * shadow_w + 3.2 * high_w, 0.0, 255.0)
        arr[:, :, 2] = np.clip(arr[:, :, 2] + 7.5 * shadow_w - 3.5 * high_w, 0.0, 255.0)
        out = Image.fromarray(arr.astype(np.uint8), mode="RGB")
    except Exception:
        out = im.convert("RGB")
    out = ImageEnhance.Contrast(out).enhance(1.07)
    out = ImageEnhance.Color(out).enhance(1.06)
    out = out.filter(ImageFilter.UnsharpMask(radius=0.95, percent=118, threshold=3))
    return out


