def restore_exact_fact_proper_nouns(narration_text, dossier=None):
    """
    V53 EXACT FACT PROPER-NOUN RESTORER (Fixes LLM phonetic drift like 'Luzale' -> 'Lusail',
    'Kilas'/'Kelesz' -> 'Quiles', 'Komoto' -> 'CFMOTO', 'Espar' -> 'Aspar', 'Veta' -> 'Veda', 'AMP' -> 'MMP'):
    1. Applies known sports/geopolitical phonetic corrections.
    2. Compares capitalized words in `narration_text` against the verified proper nouns in
       `dossier['title'] + dossier['raw_facts']` via `difflib.SequenceMatcher` (`>= 0.76`) so
       every person, circuit, city, and team name stays 100% accurate for BOTH visual search and TTS!
    """
    import difflib
    out = str(narration_text or "")
    extra_fixes = {
        r"\bluzale\b": "Lusail",
        r"\bluzail\b": "Lusail",
        r"\bmaximokilles\b": "Maximo Quiles",
        r"\bmaximo\s+killes\b": "Maximo Quiles",
        r"\bmaxim\s+killes\b": "Maximo Quiles",
        r"\bkilles\b": "Quiles",
        r"\bkelesz\b": "Quiles",
        r"\bkilas\b": "Quiles",
        r"\bkelis\b": "Quiles",
        r"\bkles\b": "Quiles",
        r"\bkomoto\b": "CFMOTO",
        r"\bespar\b": "Aspar",
        r"\byuriardi\b": "Uriarte",
        r"\bveta\b": "Veda",
        r"\bhakee\s+danish\b": "Hakim Danish",
        r"\bamp\s+system\b": "MMP system",
        r"\bgdora\b": "Ghidorah",
        r"\bgadora\b": "Ghidorah",
        r"\bghidora\b": "Ghidorah",
        r"\btohjo\b": "Toho",
        r"\btojo's\b": "Toho's",
        r"\bminus0\b": "Minus Zero",
        r"\bzillians\b": "Xiliens",

        r"\bcamber's\b": "Canberra's",
        r"\b0\.2000\b": "0.2",
        r"\b(\d+\.\d+)\s*mm\b": r"$\1 million",
        r"(\d+(?:\.\d+)?%)\s+\d+%": r"\1",
    }
    for pat_e, rep_e in extra_fixes.items():
        out = re.sub(pat_e, rep_e, out, flags=re.I)
    for pat_e, rep_e in PHONETIC_ENTITY_CORRECTIONS.items():
        out = re.sub(pat_e, rep_e, out, flags=re.I)

    if dossier:
        ref_blob = f"{dossier.get('title', '')} {' '.join(str(x) for x in (dossier.get('raw_facts') or [])[:10])}"
        true_proper = {}
        for w in re.findall(r"\b[A-Z][a-zA-Z0-9]{3,}\b", ref_blob):
            if w.lower() not in HEADLINE_STOP_VERBS_ADJS and w.lower() not in COMMON_SENTENCE_START_WORDS:
                true_proper[w.lower()] = w
        if true_proper:
            def _fix_word(m_w):
                w_cand = m_w.group(0)
                wl = w_cand.lower()
                if wl in true_proper or wl in HEADLINE_STOP_VERBS_ADJS or wl in COMMON_SENTENCE_START_WORDS:
                    return w_cand
                best_m = difflib.get_close_matches(wl, list(true_proper.keys()), n=1, cutoff=0.78)
                if best_m and abs(len(best_m[0]) - len(wl)) <= 2:
                    return true_proper[best_m[0]]
                return w_cand
            out = re.sub(r"\b[A-Z][a-zA-Z]{4,}\b", _fix_word, out)
    return out

def normalize_narration_entity_spelling(text_str, dossier=None):
    if not text_str:
        return ""
    text_str = re.sub(r"\b10[-\s]+horsepower\b", "300-horsepower", str(text_str), flags=re.I)
    text_str = re.sub(r"\bGrande\s+Pre(?:irely)?\b", "Grand Prix", text_str, flags=re.I)
    text_str = re.sub(r"\bBaya\b", "Bagnaia", text_str)
    text_str = re.sub(r"\bB(?:i)?zeki\b", "Bezzecchi", text_str)
    text_str = re.sub(r"\bQar(?:d)?\b", "Qatar", text_str)
    return restore_exact_fact_proper_nouns(text_str, dossier=dossier)

def extract_sentence_ner_and_context(beat_text, bv_dict, dossier):
    """
    V42 SENTENCE-LEVEL NAMED ENTITY RECOGNITION (NER) & CONTEXT ANALYZER:
    Analyzes `beat_text` sentence-by-sentence to identify:
    1. `persons`: Specific people named in the sentence (e.g., Marco Rubio, Yvan Gil, Mark Rutte, Rachel Reeves).
    2. `specific_entities`: Named airports, ports, agencies, companies, vessels, or historical events
       (e.g., 'Warsaw Chopin Airport', 'Madrid-Barajas Airport', 'Sofia Airport', 'Port of Piraeus',
       'Europol', 'Interpol', 'Guardia Civil', 'Greek Coast Guard', 'Germanwings', 'Jamnagar Refinery').
    3. `locations`: Specific cities, countries, and seas mentioned in THIS sentence (e.g., Warsaw, Poland,
       Barcelona, Madrid, Spain, Sofia, Bulgaria, Piraeus, Greece, Black Sea, Strait of Hormuz).
    4. `physical_objects`: Concrete visual objects/actions being described (e.g., 'bomb squad sniffer dogs',
       'cruise ship evacuation', 'runway closure', 'airline stock market', 'cargo ship').
    5. `wiki_entity_targets`: Exact Wikipedia page titles for specific facilities/organizations/events in this sentence
       (NEVER bare country names!) so we can fetch verified encyclopedia visuals of that exact entity!
    """
    clean_sent = normalize_narration_entity_spelling(beat_text)
    low_txt = clean_sent.lower()
    bv_q_raw = normalize_narration_entity_spelling((bv_dict or {}).get("photo_query") or "")

    persons = []
    specific_entities = []
    locations = []
    physical_objects = []
    wiki_entity_targets = []

    # 1. Detect Named Persons in this sentence
    p_dir = dossier.get("person_role_directory") or {}
    for p_key, (w_n, d_n, _) in p_dir.items():
        if p_key in low_txt or d_n.lower() in low_txt:
            if d_n not in persons:
                persons.append(d_n)
                wiki_entity_targets.append(w_n)
    p_tuple = detect_person_in_narration_text(clean_sent, ai_person=(bv_dict or {}).get("mentioned_person", ""), story_title=dossier.get("title", ""))
    if p_tuple and p_tuple[1] not in persons:
        persons.append(p_tuple[1])
        wiki_entity_targets.append(p_tuple[0])

    # 2. Detect Known Cities, Airports, Ports, & International Agencies in this sentence
    for k_phrase, (k_country, k_wiki) in sorted(KNOWN_WORLD_CITIES_AND_FACILITIES.items(), key=lambda x: len(x[0]), reverse=True):
        if re.search(rf"\b{re.escape(k_phrase)}\b", low_txt):
            if k_wiki not in specific_entities:
                specific_entities.append(k_wiki)
            # V50 EXACT-EVENT GUARD: Only add specific airports, ports, agencies, companies, or canals to `wiki_entity_targets`
            # (NEVER bare cities or seas like 'Ankara', 'Riyadh', 'London', 'Paris', 'Red Sea', which would return generic tourist/map photos!)
            if any(fk in k_wiki.lower() for fk in ["airport", "port of", "guard", "europol", "interpol", "pentagon", "reserve", "kremlin", "exchange", "refinery", "isro", "drdo", "nasa", "eskom", "canal", "tsmc", "asml", "nvidia", "openai", "spacex", "aramco"]) and k_wiki not in wiki_entity_targets:
                wiki_entity_targets.append(k_wiki)
            if k_country not in locations and k_country not in ("International", "NATO", "European Union"):
                locations.append(k_country)

    # 3. Detect Capitalized Multi-Word Proper Noun Phrases (e.g. 'Warsaw Chopin Airport', 'Guardia Civil', 'Greek Coast Guard', 'MV Al-Mansur', 'Arleigh Burke')
    for m_prop in re.finditer(r"\b([A-Z][a-zA-Z0-9\-]+(?:\s+(?:of|the|and|for|in)?\s*[A-Z][a-zA-Z0-9\-]+){1,3})\b", clean_sent):
        phrase = m_prop.group(1).strip()
        p_words = [w for w in phrase.split() if w.lower() not in {"the", "in", "at", "on", "by", "to", "from", "while", "when", "after", "before", "meanwhile", "within", "across", "beneath", "during", "under"}]
        if not p_words:
            continue
        clean_p = " ".join(p_words)
        if len(clean_p) >= 5 and clean_p.lower() not in COUNTRY_GEO_DB and clean_p not in specific_entities:
            specific_entities.append(clean_p)
            if any(fac_w in clean_p.lower() for fac_w in ["airport", "port", "guard", "police", "ministry", "agency", "fleet", "strait", "island", "refinery", "exchange", "bank", "court", "commission", "council", "airlines", "airways", "bridge", "canal", "dam", "station", "laboratory"]):
                if clean_p not in wiki_entity_targets:
                    wiki_entity_targets.append(clean_p)

    # 4. Detect Countries & Demonyms explicitly mentioned in this sentence
    for cnt_name in COUNTRY_GEO_DB.keys():
        if re.search(rf"\b{re.escape(cnt_name.lower())}\b", low_txt):
            if cnt_name.title() not in locations:
                locations.append(cnt_name.title())
    for dem_k, cnt_mapped in DEMONYM_TO_COUNTRY.items():
        if len(dem_k.strip()) >= 4 and re.search(rf"\b{re.escape(dem_k.strip().lower())}\b", low_txt):
            if cnt_mapped.title() not in locations:
                locations.append(cnt_mapped.title())

    # 5. Extract Concrete Physical Objects & Context Nouns from `clean_sent` + `bv_q_raw`
    extra_verb_stops = {
        "off", "hit", "hits", "deployed", "deploy", "killing", "killed", "attack", "attacks", "blast",
        "blasts", "insurers", "imports", "received", "forcing", "rippled", "scrambled", "verify", "warning",
        "uncovered", "sheer", "coordination", "raised", "eyebrows", "simultaneously", "added", "adding",
        "sparked", "testing", "limits", "affected", "scheduled", "abruptly", "diverted", "pinged",
        "executed", "unscheduled", "disembarked", "tense", "combed", "every", "idle", "conducted",
        "ultimately", "clearing", "placed", "hold", "creating", "cascading", "busiest", "underscored",
        "paralyze", "major", "least", "searches", "found", "similar", "minutes", "touchdown", "ordered",
        "immediate", "taxied", "remote", "meticulous", "escorted", "holding", "investigators", "origin",
        "cleared", "inspection", "closure", "grounding", "dozens", "other", "straining", "already",
        "busy", "summer", "series", "suspected", "triggered", "became", "epicenter", "inbound", "halted",
        "crews", "cordoned", "ushered", "temporary", "performed", "exterior", "interior", "returned",
        "clean", "remained", "heightened", "cancelling", "additional", "peak", "targeted", "prompted",
        "swept", "finding", "suspicious", "proved", "moored", "missing", "causing", "estimated", "stranded",
        "many", "whom", "missed", "crucial", "reported", "surge", "offered", "options", "pressure",
        "erupted", "frantic", "turning", "viral", "amplified", "confront", "activated", "linking",
        "single", "investigative", "platform", "reached", "worldwide", "demonstrated", "capacity",
        "mobilize", "quickly", "highlighted", "seeking", "close"
    }
    loc_and_ent_words = {w.lower() for w in re.findall(r"[A-Za-z0-9]+", " ".join(locations + specific_entities + persons))}
    for src_chunk in [clean_sent, bv_q_raw]:
        for w in re.findall(r"[A-Za-z0-9\-]{3,}", str(src_chunk or "")):
            wl = w.lower().strip("-")
            if len(wl) < 3 or wl.isdigit():
                continue
            if wl in SENTENCE_VISUAL_STOPWORDS or wl in extra_verb_stops or wl in HEADLINE_STOP_VERBS_ADJS or wl in METAPHOR_NOISE_WORDS or wl in COMMON_SENTENCE_START_WORDS:
                continue
            if wl in loc_and_ent_words or wl in {"indian", "omani", "iranian", "american", "venezuelan", "spanish", "polish", "bulgarian", "greek", "israeli", "european"}:
                continue
            if wl not in [x.lower() for x in physical_objects]:
                physical_objects.append(w)

    return {
        "clean_sentence": clean_sent,
        "persons": persons,
        "specific_entities": specific_entities,
        "locations": locations,
        "physical_objects": physical_objects,
        "wiki_entity_targets": wiki_entity_targets
    }


