def has_well_framed_face(im):
    if FACE_CASCADE is None:
        return False
    try:
        iw, ih = im.size
        sw = 480
        sh = max(int(ih * (480.0 / iw)), 270)
        gray_s = cv2.cvtColor(np.array(im.resize((sw, sh))), cv2.COLOR_RGB2GRAY)
        faces = FACE_CASCADE.detectMultiScale(gray_s, scaleFactor=1.12, minNeighbors=5, minSize=(40, 40))
        for (fx, fy, fw, fh) in faces:
            if fx > sw * 0.08 and (fx + fw) < sw * 0.92 and fy > sh * 0.08 and (fy + fh) < sh * 0.88 and fh < sh * 0.42:
                return True
    except Exception:
        pass
    return False

def fit_full_height_face_aware_1080p(im, target_w, target_h):
    resample_mode = getattr(Image, "Resampling", Image).LANCZOS
    iw, ih = im.size
    target_ratio = target_w / float(target_h)
    img_ratio = iw / float(ih)

    if target_w < target_h and img_ratio > 0.85:
        # V50 2026 VISION-OS ROUNDED 9:16 CINEMA STAGE (Preserves wide 16:9 HD clarity + sleek rounded glass card without ugly bars!):
        bg = im.copy().resize((target_w, target_h), resample_mode).filter(ImageFilter.GaussianBlur(radius=30))
        bg = ImageEnhance.Brightness(bg).enhance(0.32)
        bg = ImageEnhance.Color(bg).enhance(1.18)
        bg_rgba = bg.convert("RGBA")

        pad_x = int(target_w * 0.026)
        card_w = target_w - 2 * pad_x
        card_h = int(target_h * (0.58 if img_ratio >= 1.30 else 0.66))
        scale_c = max(card_w / float(iw), card_h / float(ih))
        rw, rh = int(iw * scale_c), int(ih * scale_c)
        fg_resized = im.resize((rw, rh), resample_mode)
        left_c = (rw - card_w) // 2
        top_c = max(0, int((rh - card_h) * 0.20))
        fg_card = fg_resized.crop((left_c, top_c, left_c + card_w, top_c + card_h))
        fg_card = fg_card.convert("RGBA")

        y_pos = int(target_h * 0.145)
        rad = 28

        # Soft ambient drop shadow
        sh_layer = Image.new("RGBA", (target_w, target_h), (0, 0, 0, 0))
        sh_draw = ImageDraw.Draw(sh_layer, "RGBA")
        sh_draw.rounded_rectangle([(pad_x + 4, y_pos + 10), (pad_x + card_w + 4, y_pos + card_h + 14)], radius=rad, fill=(0, 0, 0, 155))
        sh_layer = sh_layer.filter(ImageFilter.GaussianBlur(radius=14))
        bg_rgba.alpha_composite(sh_layer)

        # Rounded mask for the crisp 1080p foreground card
        mask_l = Image.new("L", (card_w, card_h), 0)
        ImageDraw.Draw(mask_l).rounded_rectangle([(0, 0), (card_w - 1, card_h - 1)], radius=rad, fill=255)
        bg_rgba.paste(fg_card, (pad_x, y_pos), mask_l)

        # Subtle 2px specular glass border around the cinema card
        rim_draw = ImageDraw.Draw(bg_rgba, "RGBA")
        rim_draw.rounded_rectangle([(pad_x, y_pos), (pad_x + card_w - 1, y_pos + card_h - 1)], radius=rad, outline=(255, 255, 255, 78), width=2)
        return bg_rgba.convert("RGB")

    if img_ratio >= target_ratio:
        crop_h = ih
        crop_w = int(ih * target_ratio)
        left = (iw - crop_w) // 2
        cropped = im.crop((left, 0, left + crop_w, crop_h))
        return cropped.resize((target_w, target_h), resample_mode)

    crop_w = iw
    crop_h = int(iw / target_ratio)
    top = int((ih - crop_h) * 0.20)
    cropped = im.crop((0, top, crop_w, top + crop_h))
    return cropped.resize((target_w, target_h), resample_mode)

def build_clean_1080p_stage(im, W, H):
    """
    V59 2.5D MULTI-PLANE DEPTH PARALLAX STAGE BUILDER:
    Prepares both a razor-sharp 1.12x Foreground Subject Plane (`fg`) and a deep-bokeh 1.14x Background
    Atmosphere Plane (`bg_depth`) so `extract_diverse_camera_frame_from_stage` can animate true 2.5D camera
    zoom + differential parallax on every still photo beat!
    """
    over_w, over_h = int(W * 1.12), int(H * 1.12)
    fg = fit_full_height_face_aware_1080p(im, over_w, over_h)
    bg_depth = ImageEnhance.Brightness(fg.filter(ImageFilter.GaussianBlur(radius=14))).enhance(0.42)
    return ("FULL_BLEED_25D_PARALLAX_STAGE", fg, bg_depth)


