    px_crop = (p_res.size[0] - pw_card) // 2
    py_crop = max(0, int((p_res.size[1] - ph_card) * 0.18))
    p_card_im = p_res.crop((px_crop, py_crop, px_crop + pw_card, py_crop + ph_card)).convert("RGBA")

    p_mask = Image.new("L", (pw_card, ph_card), 0)
