def _fit_font_for_width(draw_obj, text_str, start_size, min_size, max_px_width):
    sz = start_size
    while sz > min_size:
        f_cand = get_font(sz)
        w_px = draw_obj.textbbox((0, 0), text_str, font=f_cand)[2]
        if w_px <= max_px_width:
            return f_cand, w_px
        sz -= 4
    f_min = get_font(min_size)
    return f_min, draw_obj.textbbox((0, 0), text_str, font=f_min)[2]

def build_story_specific_thumbnail_hook(dossier):
    """
    V46 CATEGORY-TAILORED NARRATIVE THUMBNAIL HOOK GENERATOR:
    Builds a 2-part Narrative Hook (Line 1 = Concrete Subject/Actor, Line 2 = Dramatic Narrative Payoff/Question)
    so thumbnails NEVER show dry 2-word title slices like 'FA\'AZ TEST / PAK AIR FORCE' or 'US-ASEAN POWER / CHINA PUSHBACK'!
    """
    if dossier.get("is_mega_24h"):
        return ("24H WORLD BRIEFING", "TOP GLOBAL SHOCKS")

    sub_p = str(dossier.get("sub_pillar") or dossier.get("pillar", "GEOPOLITICS")).upper()
    arch = CATEGORY_THUMB_ARCHETYPES.get(sub_p, CATEGORY_THUMB_ARCHETYPES["GEOPOLITICS"])
    title_raw = ascii_transliterate_keep_vowels(str(dossier.get("title", ""))).strip()
    title_up = title_raw.upper()
    c_name = str(dossier.get("country_profile", {}).get("name", "GLOBAL")).upper()

    if dossier.get("ai_thumb_hook"):
        l1 = str(dossier["ai_thumb_hook"][0]).upper().strip()
        l2 = str(dossier["ai_thumb_hook"][1]).upper().strip()
        generic_banned = {"GLOBAL SHOCK", "THE REAL TRUTH", "PHYSICS BROKEN?", "TOTAL COLLAPSE?", "POLITICAL SHOCK?"}
        if l1 and l2 and f"{l1} {l2}" not in generic_banned and l1 not in generic_banned:
            first4 = " ".join(re.findall(r"[A-Z0-9']+", title_up)[:4])
            comb_l12 = " ".join(re.findall(r"[A-Z0-9']+", f"{l1} {l2}"))
            if comb_l12 != first4:
                return (fit_whole_words_limit(l1, 20), fit_whole_words_limit(l2, 20))

    age_m = re.search(r"\b(\d{2}-YEAR-OLD)\b", title_up)
    money_m = re.search(r"((?:\$|£|€|₹)\d+(?:[.,]\d+)?\s*(?:BILLION|MILLION|TRILLION|B|M|T)?|\b\d+(?:[.,]\d+)?\s*(?:%|BILLION|TRILLION))", title_up)

    stop_t = {
        "THE", "A", "AN", "IN", "ON", "AT", "TO", "FOR", "OF", "AND", "OR", "WITH", "FROM",
        "BY", "AS", "IS", "ARE", "WAS", "WERE", "WHY", "HOW", "WHAT", "WHEN", "WHERE", "WHO",
        "JUST", "NEW", "NOW", "THAT", "THIS", "THESE", "THOSE", "ITS", "THEIR", "AFTER", "OVER",
        "EXPLAINED", "BREAKING", "UPDATE", "NEWS", "REPORT", "SAYS", "SAID", "AMID", "INTO"
    }
    words = [w.strip(",.:;?!'\"") for w in title_up.split() if len(w.strip(",.:;?!'\"")) >= 3 and w.strip(",.:;?!'\"") not in stop_t]

    if age_m and sub_p in ("VIRAL_UNDERDOG_SPORTS", "SPORTS"):
        line_1 = f"{age_m.group(1)} PRODIGY"
    elif money_m and sub_p in ("STOCK_MARKETS", "BUSINESS"):
        line_1 = fit_whole_words_limit(f"{money_m.group(1).strip()} MARKET SHOCK", 20)
    elif len(words) >= 2:
        line_1 = fit_whole_words_limit(" ".join(words[:3]), 19)
    else:
        line_1 = fit_whole_words_limit(c_name, 18)

    if "CHINA" in title_up and "CHINA" not in line_1:
        line_2 = "CHINA CORNERED?"
    elif "RUSSIA" in title_up and "RUSSIA" not in line_1:
        line_2 = "MOSCOW'S NEXT MOVE?"
    elif "IRAN" in title_up and "IRAN" not in line_1:
        line_2 = "MIDDLE EAST SHIFT?"
    elif "HONDA" in title_up:
        line_2 = "HONDA STUNNED!"
    elif any(k in title_up for k in ["MONOPOLY", "CHIP", "SILICON", "NVIDIA", "AI ", "ROBOT", "QUANTUM"]):
        line_2 = "SILICON MONOPOLY?" if "MONOPOLY" in title_up else "THE AI ENDGAME!"
    elif any(k in title_up for k in ["SECRET", "HIDDEN", "NOBODY", "CABLE", "CHOKEPOINT", "CORRIDOR"]):
        line_2 = "NOBODY NOTICED THIS!" if "NOBODY" in title_up else "THE HIDDEN TRAP!"
    elif any(k in title_up for k in ["MISSILE", "DRONE", "FIGHTER", "AIR FORCE", "NAVY", "NUCLEAR", "TEST", "WEAPON"]):
        line_2 = "AIR POWER SHIFT?" if "AIR" in title_up else "DEFENSE GAMECHANGER?"
    elif any(k in title_up for k in ["VOTE", "VOTES", "ELECTION", "POLLS", "SENATE", "PARLIAMENT", "COLLAPSE"]):
        line_2 = "END OF AN ERA?" if "COLLAPSE" in title_up else "VERDICT SHOCKWAVE!"
    elif any(k in title_up for k in ["TARIFF", "SANCTION", "DEBT", "CRASH", "RALLY", "STOCK", "BILLION", "RAND", "RUPEE", "DOLLAR"]):
        line_2 = "WHO WINS BILLIONS?" if "BILLION" in title_up else "MARKET RECKONING!"
    else:
        h_idx = sum(ord(ch) for ch in title_up) % len(arch["default_l2_hooks"])
        line_2 = arch["default_l2_hooks"][h_idx]

    return (line_1, line_2)

def create_signature_wtb_brand_thumbnail(dossier, entities, unique_photos, watermark, out_path="output/WTB_1080p_Thumb_1.jpg"):
    """
    V47 CLASSIC HIGH-CTR STUDIO THUMBNAIL ENGINE (RESTORED CLEAN POSTER LOOK + CATEGORY COLORS + 100% YOUTUBE UPLOAD GUARANTEE):
    - Restores the clean, classic studio poster layout the user loved (Full-bleed 1080p hero photo + Top-Left WTB Emblem &
      Country Flag + Upper-Right 3D Tilted 2nd Story Photo Card + Lower-Right Circular Leader Portrait Medallion +
      Lower-Left 3D Extruded White Line 1 & Category-Colored Tilted Ribbon Line 2).
    - Keeps ALL V46 fixes:
      * ZERO laser lines poking into faces!
      * ZERO duplicate flag inside the right-hand photo card!
      * ZERO truncated bottom text (`_fit_font_for_width` guarantees complete words!).
      * Category-specific ribbon & border colors + story-driven narrative hooks!
      * Saves at YouTube's official `1280x720` HD thumbnail resolution (`< 650 KB` guaranteed) so `yt.thumbnails().set()`
        NEVER fails with `mediaBodyTooLarge` or falls back to a random mid-video frame!
    """
    W, H = 1920, 1080
    c_prof = dossier["country_profile"]
    c_name = fit_whole_words_limit(str(c_prof.get("name", "GLOBAL")).upper(), 18)
    pillar = str(dossier.get("pillar", "WORLD")).upper()
    sub_p = str(dossier.get("sub_pillar") or pillar).upper()
    arch = CATEGORY_THUMB_ARCHETYPES.get(sub_p) or CATEGORY_THUMB_ARCHETYPES.get(pillar) or CATEGORY_THUMB_ARCHETYPES["GEOPOLITICS"]

    prim_col = arch["primary_col"]
    sec_col = arch["secondary_col"]
    dark_tint = arch["dark_tint"]

    # Ensure high contrast when `prim_col` is bright yellow (`VOX_CENTER_TAPE` / `ARENA_MAGAZINE_COVER`)
    if sum(prim_col) > 520:
        ribbon_bg = sec_col
        ribbon_fg = prim_col
    else:
        ribbon_bg = prim_col
        ribbon_fg = sec_col if sum(sec_col) > 400 else (255, 235, 0)

    pool_ims = [it["im"] for it in (dossier.get("_cached_200_audited_pool") or []) if it.get("im") is not None]
    all_cand_ims = list(unique_photos or []) + [im for im in pool_ims if im not in (unique_photos or [])]

    face_photos = [im for im in all_cand_ims if has_well_framed_face(im)]
    non_face_photos = [im for im in all_cand_ims if im not in face_photos]

    hero_bg_im = non_face_photos[0] if non_face_photos else (all_cand_ims[0] if all_cand_ims else None)
    if hero_bg_im is None:
        hero_bg_im = fetch_verified_news_or_wiki_visual(
            dossier.get("topic_anchor", ""), dossier.get("title", ""), dossier, [], [], tag_id="thumb_hero"
        )
    if hero_bg_im is None:
        hero_bg_im = Image.new("RGB", (W, H), dark_tint)

    # Pick a genuinely DISTINCT 2nd story photo for the Upper-Right Tilted Photo Card (never a flag and never identical to hero_bg_im!)
    evidence_im = None
    for cand_im in (non_face_photos[1:] + face_photos + all_cand_ims):
        if cand_im is not hero_bg_im:
            evidence_im = cand_im
            break
    if evidence_im is None:
        evidence_im = create_distinct_editorial_composition_variant(hero_bg_im, 1)

    # LAYER 1: Full-Bleed High-Contrast Cinema Stage (Clean Center — Zero Diagonal Slash Lines!)
    base_stage = fit_full_height_face_aware_1080p(hero_bg_im, W, H)
    graded_bg = ImageEnhance.Contrast(base_stage).enhance(1.24)
    graded_bg = ImageEnhance.Color(graded_bg).enhance(1.16)
    graded_bg = ImageEnhance.Sharpness(graded_bg).enhance(1.32)

    canvas = graded_bg.convert("RGBA")

    # Smooth 2D Seamless Studio Vignette (Zero rectangular seam bands!)
    yy = np.linspace(0.0, 1.0, H, dtype=np.float32)[:, None]
    xx = np.linspace(0.0, 1.0, W, dtype=np.float32)[None, :]
    a_top = np.clip((0.14 - yy) / 0.14, 0.0, 1.0) * 160.0
    a_bot = (np.clip((yy - 0.48) / 0.52, 0.0, 1.0) ** 1.20) * 246.0
    a_right = (np.clip((xx - 0.62) / 0.38, 0.0, 1.0) ** 1.45) * 185.0
    a_combined = np.maximum(np.maximum(a_top, a_bot), a_right).astype(np.uint8)
    grad_arr = np.zeros((H, W, 4), dtype=np.uint8)
    grad_arr[:, :, 0] = dark_tint[0]
    grad_arr[:, :, 1] = dark_tint[1]
    grad_arr[:, :, 2] = dark_tint[2]
    grad_arr[:, :, 3] = a_combined
    canvas.alpha_composite(Image.fromarray(grad_arr, "RGBA"))
    draw = ImageDraw.Draw(canvas, "RGBA")

    # LAYER 2: Classic 3D Tilted Story Evidence Photo Card (`Upper-Right`, Clean & Distinct — No Laser Line!)
    ev_w, ev_h = 540, 335
    ev_card = Image.new("RGBA", (ev_w + 40, ev_h + 40), (0, 0, 0, 0))
    ev_d = ImageDraw.Draw(ev_card, "RGBA")
    ev_d.rounded_rectangle([(20, 22), (ev_w + 24, ev_h + 26)], radius=20, fill=(0, 0, 0, 215))
    ev_d.rounded_rectangle([(8, 8), (ev_w + 12, ev_h + 12)], radius=20, fill=(12, 18, 34, 255), outline=ribbon_fg + (255,), width=6)
    ev_crop = fit_full_height_face_aware_1080p(evidence_im, ev_w - 16, ev_h - 60)
    ev_crop = ImageEnhance.Contrast(ImageEnhance.Brightness(ev_crop).enhance(1.06)).enhance(1.16)
    ev_card.paste(ev_crop.convert("RGBA"), (18, 54))
    ev_d.rounded_rectangle([(12, 12), (ev_w + 8, 50)], radius=14, fill=ribbon_bg + (255,))
    card_tab_txt = f"● {arch['widget_title']} • {c_name}"
    f_ctab, _ = _fit_font_for_width(ev_d, card_tab_txt, 21, 16, ev_w - 28)
    ev_d.text((26, 18), card_tab_txt, fill=(255, 255, 255, 255), font=f_ctab)
    ev_tilted = ev_card.rotate(4.5, expand=True, resample=getattr(Image, "Resampling", Image).BICUBIC)
    canvas.alpha_composite(ev_tilted, (W - ev_tilted.size[0] - 44, 110))
    draw = ImageDraw.Draw(canvas, "RGBA")

    # LAYER 3: Hero Leader / Subject Spotlight Medallion (`Lower-Right`) ONLY when background doesn't already have a large face!
    bg_has_large_face = has_well_framed_face(hero_bg_im)
    person_hit = detect_person_in_narration_text(
        f"{dossier.get('title', '')} {' '.join(dossier.get('raw_facts', [])[:6])}",
        story_title=dossier.get("title", "")
    )
    if not person_hit and dossier.get("person_role_directory"):
        person_hit = list(dossier["person_role_directory"].values())[0]
    port_im = None
    pd_name = ""
    if person_hit and not bg_has_large_face:
        pw_name, pd_name, pr_role = person_hit
        port_im = fetch_person_portrait_image(pw_name, pd_name, pr_role)

    if port_im is not None and not bg_has_large_face:
        ava_sz = 355
        ava_x, ava_y = W - ava_sz - 74, 468
        for r_gl in range(ava_sz // 2 + 28, ava_sz // 2 + 4, -5):
            a_gl = int(90 * (1.0 - (r_gl - ava_sz // 2) / 28.0))
            draw.ellipse([(ava_x + ava_sz // 2 - r_gl, ava_y + ava_sz // 2 - r_gl), (ava_x + ava_sz // 2 + r_gl, ava_y + ava_sz // 2 + r_gl)], fill=ribbon_fg + (a_gl,))
        mask = Image.new("L", (ava_sz, ava_sz), 0)
        ImageDraw.Draw(mask).ellipse([(0, 0), (ava_sz, ava_sz)], fill=255)
        draw.ellipse([(ava_x - 9, ava_y - 9), (ava_x + ava_sz + 9, ava_y + ava_sz + 9)], fill=(10, 16, 30, 255), outline=ribbon_fg + (255,), width=7)
        draw.ellipse([(ava_x - 3, ava_y - 3), (ava_x + ava_sz + 3, ava_y + ava_sz + 3)], outline=(255, 255, 255, 245), width=3)
        p_resized = fit_full_height_face_aware_1080p(port_im.convert("RGB"), ava_sz, ava_sz)
        p_resized = ImageEnhance.Contrast(ImageEnhance.Sharpness(p_resized).enhance(1.28)).enhance(1.14)
        canvas.paste(p_resized.convert("RGBA"), (ava_x, ava_y), mask)

        if pd_name:
            lbl_p = fit_whole_words_limit(pd_name.upper(), 20)
            f_p, pw_txt = _fit_font_for_width(draw, lbl_p, 25, 18, 315)
            pw_box = pw_txt + 42
            px0 = ava_x + (ava_sz - pw_box) // 2
            py0 = ava_y + ava_sz - 20
            draw.rounded_rectangle([(px0 + 4, py0 + 5), (px0 + pw_box + 4, py0 + 48)], radius=12, fill=(0, 0, 0, 225))
